# Stories for albums 601–650 (long format agreed with the owner: three paragraphs + a listening tip,
# ~220 words per story (min ~200), three picks with ~12-word notes). Original Hebrew; facts checked on the web, uncertain ones softened.
# Used by tools/batches/build_601_650.py; later edits: python3 tools/apply_stories.py stories_601_650
STORIES = {}
def add(n, story, picks): STORIES[n] = {'story': story, 'picks': picks}

add(601, [
'''לדיסמית׳ בלאק מבאזו היא מקהלה גברית מדרום אפריקה, שהקים ג׳וזף שבללה בשנות השישים. השם שלה מספר את הסיפור: לדיסמית׳ היא העיירה שממנה באו, "בלאק" על שם השוורים השחורים, החזקים ביותר בחווה, ו"מבאזו" פירושו גרזן, שכורת את כל המתחרים. הם שרים בסגנון זולו בשם איסיקטאמייה, שנולד בקרב פועלי מכרות שגרו הרחק מבתיהם, וערכו ביניהם תחרויות שירה בלילות שבת. Shaka Zulu, שיצא ב־1987, הפיק פול סיימון, שעבד איתם שנה קודם על Graceland (אלבום 577).''',
'''כמעט אין כאן כלים: רק קולות, עשרה גברים ויותר, שבונים יחד הרמוניות עמוקות, רכות וחמות. שבללה שר את הקול המוביל, והמקהלה עונה לו בקולות בס עמוקים, בלחישות, בצקצוקים ובנקישות לשון שאופייניות לשפת הזולו. השירים עוסקים באמונה, בגעגועים הביתה, בגשם, באהבה ובהיסטוריה של עם הזולו, ושאקה זולו, המלך הגדול של המאה התשע־עשרה, נותן לאלבום את שמו. יש גם כמה שורות באנגלית, שנועדו לקהל החדש שהכיר אותם דרך פול סיימון. כשהם שרים יחד, נדמה שמדובר בכלי נגינה אחד ענק ונושם.''',
'''האלבום זכה בפרס הגראמי, והפך את המקהלה לאחד ההרכבים האפריקאיים המוכרים בעולם. בשנים הבאות הם הופיעו בכל העולם, שרו בטקסים רשמיים, ומאוחר יותר אף שרו לצד נלסון מנדלה אחרי שחרורו. ג׳וזף שבללה מת ב־2020, אבל בניו ונכדיו ממשיכים את המקהלה עד היום.''',
'''שמעו את האלבום בשקט, אולי עם אוזניות, ונסו להפריד בין הקולות: הבס העמוק, המקהלה באמצע והקול הגבוה שמוביל. אחר כך חזרו ל־Homeless מתוך Graceland (אלבום 577), כדי לשמוע איך הם נשמעו לצד פול סיימון.''',
], [
('Unomathemba', 'שיר רך ומתנגן, עם קול מוביל חם ומקהלה שעונה לו בעדינות.'),
('King of Kings', 'מזמור אמונה עמוק וחגיגי, שבו ההרמוניות מגיעות לשיא מרגש במיוחד.'),
('Rain, Rain, Beautiful Rain', 'שיר שמח על גשם, עם מילים באנגלית וקולות שמחקים טיפות.'),
])

add(602, [
'''לייבאך קמו ב־1980 בעיירת הכורים טרבובליה שבסלובניה, אז חלק מיוגוסלביה הקומוניסטית. הם היו חלק מקבוצת אמנים בשם NSK, שהשתמשה בסמלים, במדים ובשפה של משטרים טוטליטריים, כדי לחשוף, בדרך מבהילה ואירונית, איך כוח ותעמולה עובדים. השלטונות ביוגוסלביה לא הבינו את הבדיחה, ובמשך שנים נאסר עליהם להופיע בשם הלהקה. Opus Dei, שיצא ב־1987, הוא האלבום שהביא אותם לקהל בינלאומי.''',
'''הצליל כבד, צבאי וחגיגי: תופים כמו במצעד, מקהלות גבריות, קרני יער, צלילים תעשייתיים ושירה עמוקה ומחוספסת בגרמנית ובאנגלית. הרגע המפורסם באלבום הוא Leben heißt Leben, גרסה לשיר הפופ האוסטרי השמח Life Is Life, שלייבאך הפכו להמנון צבאי מאיים. כך הם שאלו שאלה פשוטה: מה ההבדל בין שיר עליז שכולם שרים יחד לבין תעמולה? גם Geburt einer Nation, גרסה לשיר One Vision של קווין, הופך את המילים על "חזון אחד" לדבר מפחיד. גם השירים המקוריים באלבום בנויים כמו טקסים, עם חזרות, קריאות ומקצבים שמזכירים צעדה של צבא.''',
'''לייבאך נחשבו לאחת הלהקות המשפיעות של המוזיקה התעשייתית, והשפיעו על להקות גרמניות כמו ראמשטיין. גם היום הם ממשיכים לעורר מחלוקת: ב־2015 הם היו הלהקה המערבית הראשונה שהופיעה בצפון קוריאה, בהופעה שהייתה גם היא חלק מאותו משחק מבלבל בין ביקורת להערצה. רבים לא ידעו בהתחלה אם הם מעריצים את הסמלים האלה או צוחקים עליהם, וזה בדיוק מה שהלהקה רצתה.''',
'''כדאי לשמוע את Leben heißt Leben יחד עם המקור, Life Is Life של להקת אופוס. ההשוואה תעזור להבין את ההומור החשוך של לייבאך, ואת מה שהם ניסו להגיד.''',
], [
('Leben heißt Leben', 'שיר פופ עליז שהפך להמנון צבאי מאיים, הרגע המפורסם של האלבום.'),
('Geburt einer Nation', 'גרסה מפחידה ל־One Vision של קווין, עם תופים ומקהלה גברית.'),
('Opus Dei', 'גרסה נוספת לאותו שיר, בעיבוד אחר, עם קרני יער וקצב צועד.'),
])

add(603, [
'''נאפאלם דת׳ קמו בכפר קטן ליד בירמינגהם שבאנגליה, בתחילת שנות השמונים, כלהקת פאנק של נערים. מהר מאוד הם הלכו לכיוון קיצוני יותר: מהיר יותר, רועש יותר וקצר יותר מכל מה שנשמע עד אז. Scum, שיצא ב־1987, הוא אלבום הבכורה שלהם, ושני צדדיו הוקלטו בהפרש של כמה חודשים עם הרכבים כמעט שונים לגמרי: רק המתופף מיק האריס ניגן בשניהם. האלבום נחשב לאחד הראשונים, ואולי הראשון, בסגנון שנקרא "גריינדקור".''',
'''יש כאן עשרים ושמונה שירים בפחות משלושים וחמש דקות. רובם נמשכים פחות מדקה, וכמה מהם רק שניות ספורות. התופים מכים בקצב מהיר כל כך שהוא נשמע כמו רעש לבן, הגיטרות מזמזמות כמו מסור, והשירה היא בעיקר נהמות וצעקות. You Suffer, אחד השירים, נמשך פחות משתי שניות, ונכנס לספר השיאים של גינס כשיר המוקלט הקצר ביותר. מאחורי הרעש יש מילים פוליטיות: נגד קפיטליזם, נגד מלחמה, נגד גזענות ובעד זכויות בעלי חיים.''',
'''השדרן ג׳ון פיל מה־BBC התלהב מהם והשמיע אותם ברדיו, וכך להקה מחתרתית לגמרי הגיעה לקהל רחב. Scum השפיע על כל המטאל הקיצוני שבא אחריו, ונאפאלם דת׳ עצמם ממשיכים להופיע עד היום, אמנם בהרכב אחר לגמרי. זה אלבום שהגבולות של מה שנחשב "מוזיקה" נמתחים בו עד הקצה. גם להקות רבות מחוץ לעולם המטאל למדו ממנו שאין גבול לכמה מהירה ועזה מוזיקה יכולה להיות.''',
'''זה אחד האלבומים הקשים ביותר לשמיעה ברשימה כולה. אם אתם רוצים לנסות, התחילו ב־Scum, שיר הנושא, שיש בו פתיחה איטית יחסית, ואחר כך תנו ל־You Suffer לעבור. זה ייקח שנייה אחת בלבד.''',
], [
('Scum', 'שיר הנושא, עם פתיחה איטית ומאיימת יחסית לפני שהכל מתפרץ.'),
('You Suffer', 'השיר הקצר בעולם, פחות משתי שניות, שנכנס לספר השיאים של גינס.'),
('Instinct of Survival', 'שיר ארוך יחסית, עם ריף כבד ומילים זועמות על הישרדות.'),
])

add(604, [
'''סוניק יות׳ כבר הופיעו כאן עם EVOL (אלבום 574), שבו התחילו להפוך את הרעש לשירים. Sister, שיצא ב־1987, הוא הצעד הבא: האלבום הקצר, החד והממוקד ביותר שלהם עד אז. החברים, ת׳רסטון מור, קים גורדון, לי רנאלדו וסטיב שלי, הושפעו בכתיבתו מסופר המדע הבדיוני פיליפ ק. דיק, שאחותו התאומה מתה זמן קצר אחרי הלידה, וכל חייו חש את חסרונה. משם בא השם, "אחות".''',
'''הגיטרות עדיין מכוונות בדרכים מוזרות, עדיין שורטות ומזמזמות, אבל השירים קצרים, מהירים וכמעט פופיים. הלהקה הקליטה באולפן אנלוגי ישן, והצליל חם, גס ומלא נוכחות. Schizophrenia פותח במנגינה חולמנית, שבה מור וגורדון שרים לסירוגין על אדם שמאבד את דעתו. Catholic Block מהיר ופאנקי. Pacific Coast Highway, שגורדון שרה, הוא נסיעה מאיימת בכביש החוף של קליפורניה, ו־Stereo Sanctity מתפוצץ בסערה של רעש. Tuff Gnarl ו־White Kross מהירים וסוערים, ו־Hot Wire My Heart הוא גרסה לשיר של להקת פאנק מסן פרנסיסקו.''',
'''רבים רואים ב־Sister את האלבום שבו סוניק יות׳ מצאו את האיזון המושלם בין רעש לשיר, ממש לפני Daydream Nation (אלבום 630), שנחשב ליצירת המופת שלהם. האלבום השפיע על להקות רבות של שנות התשעים, שלמדו ממנו שאפשר להיות ניסיוניים ועדיין לכתוב שירים שנכנסים לראש. הם גם הראו שלהקה עצמאית לגמרי יכולה לפתח צליל משלה, בלי לוותר על שום דבר בשביל ההצלחה.''',
'''שמעו את Schizophrenia, ושימו לב איך הגיטרות של מור ורנאלדו משתלבות כמו שני קולות שמדברים. אחר כך עברו ל־Daydream Nation (אלבום 630), שבו הלהקה לוקחת את הכל עוד צעד קדימה.''',
], [
('Schizophrenia', 'הפותח, מנגינה חולמנית ושירה לסירוגין על אדם שמאבד את דעתו.'),
('Pacific Coast Highway', 'נסיעה מאיימת בכביש החוף, בקולה הקר של קים גורדון.'),
('(I Got a) Catholic Block', 'שיר מהיר ופאנקי, עם גיטרות שורטות ואנרגיה שלא נגמרת.'),
])

add(605, [
'''הטריפידס באו מפרת׳ שבמערב אוסטרליה, אחת הערים המבודדות בעולם, ובמרכזם עמד הזמר וכותב השירים דייוויד מקומב. הם עברו ללונדון באמצע שנות השמונים, וזכו שם להערכה גדולה של מבקרים, אבל לא להצלחה מסחרית גדולה. Calenture, שיצא ב־1987, הוא האלבום הגדול והמושקע ביותר שלהם, והראשון בחברת תקליטים גדולה. השם מתאר מחלה ישנה של מלחים, שגורמת להם לראות בים שדות ירוקים ולרצות לקפוץ אליו.''',
'''המוזיקה רחבה ודרמטית, עם כלי מיתר, קלידים, גיטרות מהדהדות ותופים גדולים, כמו נוף פתוח של מדבר וים. מקומב שר בקול עמוק ומלא רגש על אהבה נואשת, על געגועים, על בדידות ועל הנופים העצומים של אוסטרליה, שבהם אדם נראה קטן מאוד. Bury Me Deep in Love הוא שיר אהבה גדול, כמעט כמו מזמור. A Trick of the Light קצבי וקליט. Jerdacuttup Man מספר סיפור מוזר ומפחיד שמתרחש בנוף הפראי של מערב אוסטרליה. השירים נשמעים כמו סיפורים קצרים, עם דמויות, מקומות ומזג אוויר, ומקומב כותב כמו סופר.''',
'''הטריפידס התפרקו בסוף שנות השמונים, ומקומב מת ב־1999, בגיל 36. מאז הם התגלו מחדש, ונחשבים היום לאחת הלהקות החשובות של אוסטרליה. Bury Me Deep in Love הפך לשיר אהוב מאוד באוסטרליה, ובשנים האחרונות יצאו מהדורות מורחבות של כל האלבומים שלהם. רבים משווים אותם לבני דורם הגו־ביטווינס, אבל הצליל של הטריפידס גדול, אפל ודרמטי יותר.''',
'''שמעו את Bury Me Deep in Love בקול רם, ותנו למקהלה ולכלי המיתר לגדול. ואם אתם אוהבים את הצליל הזה, נסו גם את 16 Lovers Lane של הגו־ביטווינס (אלבום 619), שכניהם מבריסביין.''',
], [
('Bury Me Deep in Love', 'שיר אהבה גדול ומרגש, כמעט מזמור, עם מקהלה וכלי מיתר.'),
('A Trick of the Light', 'שיר קצבי וקליט, עם גיטרות מהדהדות וקול עמוק ונלהב.'),
('Jerdacuttup Man', 'סיפור מוזר ומפחיד שמתרחש בנוף הפראי והריק של מערב אוסטרליה.'),
])

add(606, [
'''אחרי Thriller (אלבום 507), האלבום הנמכר בכל הזמנים, מייקל ג׳קסון עמד מול משימה כמעט בלתי אפשרית: להמשיך. הוא עבד שוב עם המפיק קווינסי ג׳ונס, בפעם האחרונה, וכתב בעצמו את רוב השירים. Bad יצא ב־1987, וחמישה מהסינגלים שלו הגיעו למקום הראשון במצעד האמריקאי, שיא שלא היה לפני כן לאף אלבום. הסיבוב העולמי שבא אחריו היה אחד הגדולים בהיסטוריה.''',
'''הצליל קשה וחד יותר מבעבר: תופים אלקטרוניים חזקים, סינתיסייזרים, גיטרות ובס פאנקי. Bad, שיר הנושא, הוא שיר אגרסיבי ומלא ביטחון, והקליפ שלו, באורך של סרט קצר, ביים מרטין סקורסזה. Smooth Criminal מהיר ומתוח, וידוע בקליפ שבו ג׳קסון ורקדניו נוטים קדימה בזווית שנראית בלתי אפשרית. Man in the Mirror הוא שיר גוספל על שינוי שמתחיל בעצמך, עם מקהלה גדולה. The Way You Make Me Feel קליל ושמח, ו־Dirty Diana הוא שיר רוק כבד עם סולו גיטרה. Liberian Girl רך וחלומי, ו־Leave Me Alone, שנוסף רק לגרסת הדיסק, הוא שיר זועם על העיתונות.''',
'''Bad לא הגיע לגבהים של Thriller, אבל מכר עשרות מיליוני עותקים, והוכיח שג׳קסון יודע להמציא את עצמו מחדש. הוא גם הראה כמה ג׳קסון נעשה אמן שלם: כותב, מעבד, זמר ורקדן, שחושב על כל שיר גם כתמונה וכריקוד. רבים מהשירים באלבום הפכו ללהיטים בכל העולם, וחלקם מושמעים עד היום במסיבות ובחתונות.''',
'''שמעו את Man in the Mirror, ושימו לב לרגע שבו המקהלה נכנסת והשיר הופך לגוספל. אחר כך השוו ל־Off the Wall (אלבום 449), כדי לשמוע כמה ג׳קסון השתנה בשמונה שנים.''',
], [
('Man in the Mirror', 'שיר גוספל על שינוי שמתחיל בעצמך, עם מקהלה גדולה ומרגשת.'),
('Smooth Criminal', 'שיר מהיר ומתוח עם בס פועם, ואחד הקליפים המפורסמים של ג׳קסון.'),
('The Way You Make Me Feel', 'שיר קליל ושמח על התאהבות, עם קצב שמזמין לרקוד.'),
])

add(607, [
'''הפט שופ בויז הם צמד מלונדון: ניל טננט, שהיה עיתונאי במגזין מוזיקה לנוער, וכריס לואו, שלמד אדריכלות. הם נפגשו במקרה בחנות אלקטרוניקה בלונדון, וגילו שהם אוהבים את אותה מוזיקה: פופ אלקטרוני, דיסקו ושירים עם מילים חכמות. Actually, שיצא ב־1987, הוא אלבומם השני, ובו הם בשיאם: שירי ריקוד גדולים ומבריקים, עם מילים עצובות, אירוניות ופוליטיות על בריטניה של ת׳אצ׳ר.''',
'''הצליל עשוי סינתיסייזרים, מכונות תופים, מקהלות ותזמורות, וטננט שר מעל הכל בקול שקט, כמעט מדבר, קריר ומפוכח. It's a Sin, שהגיע למקום הראשון בבריטניה, מתאר ילדות בבית ספר קתולי ותחושת אשמה, בצליל דרמטי כמו אופרה. What Have I Done to Deserve This? הוא דואט עם הזמרת דאסטי ספרינגפילד, שהחזיר אותה למצעדים. Rent מספר על מערכת יחסים שבה אהבה וכסף מתערבבים. Heart הוא שיר אהבה קליל, ו־King's Cross מסיים בתיאור עצוב של תחנת רכבת לונדונית ושל אנשים שנשארו מאחור. Shopping הוא שיר קצבי ומצחיק על כלכלה וכסף, שבו כל מה שאפשר לקנות נמכר.''',
'''האלבום הפך את הפט שופ בויז לאחד הצמדים המצליחים בעולם, והם נשארו פעילים ומוערכים עד היום. רבים רואים בהם את הדוגמה הטובה ביותר לכך שפופ ריקודים יכול להיות גם חכם, אישי ועצוב. הם גם הראו שמוזיקה אלקטרונית יכולה להיות מרגשת לא פחות מרוק, ושאפשר לרקוד ולחשוב באותו הזמן.''',
'''שמעו את It's a Sin בקול רם, ואחר כך את King's Cross בשקט: שני הקצוות של האלבום. ואם אהבתם, נסו את Non-Stop Erotic Cabaret של סופט סל (אלבום 482), עוד צמד אלקטרוני בריטי.''',
], [
("It's a Sin", 'להיט דרמטי כמו אופרה, על ילדות בבית ספר קתולי ותחושת אשמה.'),
('What Have I Done to Deserve This?', 'דואט עם דאסטי ספרינגפילד, שהחזיר אותה למצעדים אחרי שנים.'),
("King's Cross", 'הסוגר, תיאור עצוב של תחנת רכבת ושל אנשים שנשארו מאחור.'),
])

add(608, [
'''יו־2 באו מדבלין שבאירלנד, וכבר הופיעו כאן עם War (אלבום 527), אלבום פוליטי וסוער. אחריו הם עבדו עם המפיקים בריאן אינו ודניאל לנואה, ונמשכו יותר ויותר לאמריקה: לנופים שלה, למוזיקת השורשים שלה, לבלוז, לגוספל ולקאנטרי, אבל גם למלחמות ולעוולות שלה. The Joshua Tree, שיצא ב־1987, הוא התוצאה, והוא הפך אותם בבת אחת ללהקה הגדולה בעולם. את העטיפה צילם אנטון קורביין במדבר של קליפורניה, ושם האלבום לקוח מעץ מדברי שגדל שם.''',
'''הצליל רחב ופתוח כמו מדבר: הגיטרה של דה אדג׳ מהדהדת ומנצנצת, הבס של אדם קליטון והתופים של לארי מאלן ג׳וניור יציבים ועמוקים, ובונו שר בקול גדול, מתחנן ונלהב. Where the Streets Have No Name פותח באורגן שקט, שהגיטרה נכנסת לתוכו לאט, עד שהשיר כולו מתרומם. I Still Haven't Found What I'm Looking For הוא שיר גוספל על חיפוש רוחני שלא נגמר. With or Without You הוא שיר אהבה כואב, שנבנה לאט לאט לשיא. Bullet the Blue Sky זועם על התערבות אמריקה במלחמות במרכז אמריקה, ו־Running to Stand Still מתאר זוג צעיר שנופל להתמכרות בשכונה ענייה בדבלין.''',
'''שני שירים מהאלבום הגיעו למקום הראשון במצעד האמריקאי, והאלבום עצמו זכה בגראמי לאלבום השנה ומכר עשרות מיליוני עותקים. הוא הפך את יו־2 לאחת הלהקות הגדולות בתולדות הרוק, ומופיע שוב ושוב ברשימות של האלבומים הגדולים בכל הזמנים.''',
'''שמעו את שלושת השירים הראשונים ברצף, כמו שהם מסודרים באלבום: שלושה להיטים גדולים, אחד אחרי השני. ואחר כך שמעו את Running to Stand Still בשקט, כדי לשמוע את הצד העדין של הלהקה.''',
], [
('Where the Streets Have No Name', 'פותח באורגן שקט, והגיטרה נכנסת לאט עד שהשיר כולו מתרומם לשמיים.'),
("I Still Haven't Found What I'm Looking For", 'שיר גוספל על חיפוש רוחני שלא נגמר, עם מקהלה ותופים רכים.'),
('With or Without You', 'שיר אהבה כואב, שנבנה לאט לאט עד לשיא רגשי גדול ומשחרר.'),
])

add(609, [
'''טרנס טרנט דארבי נולד בניו יורק, גדל בבית של כומר, שירת בצבא האמריקאי בגרמניה, ושם התחיל לשיר בלהקות. משם עבר ללונדון, וב־1987 הוציא את אלבום הבכורה שלו, עם השם הארוך והיומרני Introducing the Hardline According to Terence Trent D'Arby. הוא הכריז בראיונות שהאלבום שלו טוב יותר מ־Sgt. Pepper של הביטלס, והעיתונות הבריטית לא ידעה אם לצחוק או להתרשם. האלבום הגיע למקום הראשון במצעד הבריטי, ודארבי הפך לכוכב בן לילה.''',
'''המוזיקה מחברת סול של שנות השישים, כמו של סם קוק ואוטיס רדינג, עם פאנק, רוק ופופ של שנות השמונים. הקול של דארבי גמיש, צרוד ומלא אנרגיה, ועובר בקלות מלחישה לצעקה. Wishing Well, שהגיע למקום הראשון באמריקה, הוא שיר רך עם קצב פאנקי וקולות רקע מתוקים. Sign Your Name הוא בלדה איטית וחושנית, עם אווירה של לילה. Dance Little Sister קצבי ומשמח, ו־If You Let Me Stay הוא הבטחת אהבה סוערת ונואשת. Who's Loving You, שיר של סמוקי רובינסון, מושר כמעט בלי ליווי.''',
'''דארבי זכה בגראמי, אבל האלבומים הבאים שלו נכשלו, והוא התרחק מתעשיית המוזיקה. ב־2001 הוא שינה את שמו לסננדה מאיטרייה, וממשיך להקליט ולהוציא מוזיקה בעצמו, הרחק מהמצעדים. Introducing the Hardline נשאר עדות לרגע שבו כוכב סול חדש נראה כאילו הוא הולך לכבוש את העולם.''',
'''שמעו את Sign Your Name בערב, באור עמום, ושימו לב לקול. ואם אתם רוצים לשמוע את השורשים שלו, נסו את Otis Blue של אוטיס רדינג (אלבום 51).''',
], [
('Wishing Well', 'הלהיט שהגיע למקום הראשון באמריקה, רך ופאנקי עם קולות רקע מתוקים.'),
('Sign Your Name', 'בלדה איטית וחושנית עם אווירה של לילה, אחד השירים היפים שלו.'),
("Who's Loving You", 'שיר של סמוקי רובינסון, שמושר כמעט בלי ליווי, רק קול גמיש ונרגש.'),
])

add(610, [
'''הפוגס כבר הופיעו כאן עם Rum Sodomy & the Lash (אלבום 555), שבו חיברו מוזיקה עממית אירית עם אנרגיה של פאנק. If I Should Fall from Grace with God, שיצא ב־1988, הוא אלבומם השלישי, והגדול והמגוון ביותר שלהם. את האלבום הפיק סטיב לילייווייט, ושני חברים חדשים הצטרפו ללהקה: טרי וודס, נגן ותיק של מוזיקה עממית אירית, ופיל שברון, גיטריסט וכותב שירים. שיין מקגואן עדיין כותב את רוב השירים, וקולו נשמע כאן חזק ומלא חיים.''',
'''האלבום יוצא למסע מסביב לעולם: יש בו קצב ספרדי ב־Fiesta, מנגינות טורקיות ב־Turkish Song of the Damned, ג׳אז ישן ומוזיקת רחוב, לצד ריקודים איריים מהירים ובלדות שקטות. Fairytale of New York, דואט עם הזמרת קירסטי מקול, הוא סיפור של זוג מהגרים איריים בניו יורק שמתווכחים בליל חג המולד, בין חלומות שהתנפצו לאהבה שנשארה. Thousands Are Sailing, שכתב פיל שברון, מספר על המהגרים האיריים שהגיעו לאמריקה, ועל אלה שלא שרדו את המסע. שיר הנושא פותח באנרגיה סוחפת, כמו ריקוד בפאב. Bottle of Smoke הוא שיר מהיר ומשוגע על הימור במרוצי סוסים, שכמעט אי אפשר לעמוד בקצב שלו.''',
'''Fairytale of New York הפך לאחד משירי חג המולד האהובים בבריטניה ובאירלנד, וחוזר למצעדים כמעט בכל דצמבר, עשרות שנים אחרי שיצא. האלבום הוא גם השיא המסחרי של הפוגס, ורבים רואים בו את האלבום הטוב ביותר שלהם, לפני ששיין מקגואן נאלץ לעזוב את הלהקה בשנים שאחרי.''',
'''שמעו את Fairytale of New York ואחריו את Thousands Are Sailing: שני סיפורים על מהגרים אירים באמריקה, אחד מר ומצחיק ואחד עצוב ומרגש. ואחר כך חזרו ל־A Pair of Brown Eyes מ־Rum Sodomy & the Lash (אלבום 555).''',
], [
('Fairytale of New York', 'דואט עם קירסטי מקול על זוג מהגרים בניו יורק בליל חג המולד, מר ומרגש.'),
('Thousands Are Sailing', 'שיר יפה ועצוב על המהגרים האיריים שהגיעו לאמריקה, ועל אלה שלא שרדו.'),
('Fiesta', 'שיר שמח וסוער בקצב ספרדי, עם כלי נשיפה ואקורדיון, כמו חגיגה ברחוב.'),
])

add(611, [
'''לאונרד כהן, המשורר והזמר הקנדי, כבר הופיע כאן עם שלושת אלבומיו הראשונים (אלבומים 114, 168 ו־228), שבהם שר בשקט, עם גיטרה אקוסטית. בשנות השמונים הקריירה שלו כמעט נעצרה: חברת התקליטים האמריקאית סירבה אפילו להוציא את אחד האלבומים שלו. I'm Your Man, שיצא ב־1988, כשכהן היה בן 53, הפתיע את כולם: הוא נשמע מודרני, מצחיק ואפל, והחזיר את כהן לקדמת הבמה, במיוחד באירופה.''',
'''במקום גיטרה אקוסטית יש כאן סינתיסייזרים, מכונות תופים, קולות רקע נשיים ותזמורת קטנה, וכהן שר בקול עמוק ונמוך יותר מאי פעם, כמעט לוחש. First We Take Manhattan פותח בקצב אלקטרוני קר, ומדבר על נקמה ועל מהפכה מוזרה. Everybody Knows הוא רשימה צינית של כל מה ש"כולם יודעים" על העולם: שהקוביות מזויפות, שהמלחמה נגמרה ושהטובים הפסידו. שיר הנושא הוא הבטחת אהבה מצחיקה ומרגשת, ו־Take This Waltz הוא תרגום לשיר של המשורר הספרדי פדריקו גרסיה לורקה, בקצב ואלס ישן. Tower of Song, הסוגר, הוא שיר על הזדקנות ועל עבודת כותב השירים, ובו כהן צוחק על עצמו שנולד "עם מתנה של קול זהב".''',
'''האלבום פתח פרק חדש בחייו של כהן, שהמשיך לכתוב ולהופיע עד מותו ב־2016. רבים מהשירים שלו מכאן הפכו לקלאסיקות שזמרים רבים מבצעים עד היום.''',
'''שמעו את Tower of Song לאט, והקשיבו למילים: זה אחד השירים היפים ביותר על כתיבת שירים. ואחר כך חזרו ל־Songs of Leonard Cohen (אלבום 114), כדי לשמוע איך הוא נשמע עשרים שנה קודם.''',
], [
('First We Take Manhattan', 'פותח בקצב אלקטרוני קר, עם מילים מסתוריות על נקמה ועל מהפכה מוזרה.'),
('Everybody Knows', 'רשימה צינית ומבריקה של כל מה שכולם יודעים על העולם ולא אומרים.'),
('Tower of Song', 'שיר על הזדקנות ועל כתיבת שירים, שבו כהן צוחק על הקול שלו.'),
])

add(612, [
'''מייק סקוט, הזמר והכותב הסקוטי שעמד בראש הווטרבויז, התחיל עם צליל שהוא עצמו כינה "המוזיקה הגדולה": רוק רחב, עם שירים דרמטיים וכלי נשיפה, כמו של ספרינגסטין או יו־2. באמצע שנות השמונים הוא עבר לגור בדבלין, ואחר כך בכפר קטן בחוף המערבי של אירלנד, ושם התאהב במוזיקה העממית האירית והסקוטית, בקאנטרי ובגוספל. Fisherman's Blues, שיצא ב־1988, הוקלט במשך כמעט שלוש שנים, בדבלין, בסן פרנסיסקו ובבית ישן באירלנד, ונבחרו בו רק חלק קטן מעשרות השירים שהוקלטו.''',
'''כאן הכינור של סטיב וויקהאם מוביל את הלהקה, לצד מנדולינה, אקורדיון, פסנתר וגיטרות אקוסטיות. הקול של סקוט צרוד ונלהב, והשירים מלאים בשמחה של מוזיקאים שמגלים עולם חדש. שיר הנושא הוא שיר על החלום לחיות חיים פשוטים, כמו דייג בים, והוא נשמע כמו ריצה חופשית בשדה. And a Bang on the Ear הוא שיר מצחיק ונוסטלגי על כל הנשים שסקוט אהב. Sweet Thing הוא גרסה לשיר של ואן מוריסון מ־Astral Weeks (אלבום 132). The Stolen Child, הסוגר, הוא שיר של המשורר האירי ו.ב. ייטס, שמוקרא בקול עמוק על רקע מוזיקה עדינה. When Will We Be Married? הוא ריקוד עממי שמח, שבו כל הלהקה נשמעת כמו חבורה בחתונה כפרית.''',
'''האלבום הפך לאחד האלבומים האהובים של אירלנד ושל הרוק הבריטי, ושיר הנושא מושר עד היום בפאבים ובחתונות. הוא השפיע על הרבה להקות שחיברו בין רוק למוזיקה עממית.''',
'''שמעו את האלבום כשאתם בדרך, בנסיעה ארוכה או בטיול. ואחרי Sweet Thing, חזרו למקור של ואן מוריסון ב־Astral Weeks (אלבום 132), כדי להשוות.''',
], [
("Fisherman's Blues", 'שיר הנושא, החלום לחיים פשוטים כמו דייג בים, עם כינור סוחף ומשמח.'),
('And a Bang on the Ear', 'שיר מצחיק ונוסטלגי על כל הנשים שסקוט אהב, אחת אחרי השנייה.'),
('The Stolen Child', 'שיר של המשורר ייטס, מוקרא בקול עמוק על רקע מוזיקה אירית עדינה.'),
])

add(613, [
'''פישבון קמו בלוס אנג׳לס בסוף שנות השבעים, שישה נערים שחורים שהכירו בבית הספר. הם אהבו הכל: סקא, פאנק, פאנק־רוק, מטאל, סול, ג׳אז ורגאיי, וסירבו לבחור. בהופעות הם היו פרועים, קפצו מהבמה וניגנו בעוצמה מטורפת, והזמר והסקסופוניסט אנג׳לו מור היה אחד הפרפורמרים הסוערים של התקופה. Truth and Soul, שיצא ב־1988, הוא אלבומם השני באורך מלא, ובו הסגנונות השונים מתחברים לצליל אחד.''',
'''האלבום נפתח ב־Freddie's Dead, גרסה כבדה ומהירה לשיר של קרטיס מייפילד מ־Superfly (אלבום 246), עם גיטרות רוק וכלי נשיפה. Ma and Pa הוא שיר אישי ונוגע על משפחה ועל הורים. Pouring Rain מתחיל רך ונוגה ומתפרץ לרוק, ו־Bonin' in the Boneyard הוא פאנק קופצני ומשוגע. יש כאן גם שירים פוליטיים על גזענות ועל החיים בשכונות העניות של לוס אנג׳לס, אבל תמיד עם קצב שגורם לרקוד. כלי הנשיפה, הבס החזק והשירה הגמישה של מור הופכים כל שיר להופעה קטנה.''',
'''פישבון לא הפכו לכוכבים גדולים, אבל השפיעו מאוד על להקות שהצליחו אחריהם, כמו הרד הוט צ׳ילי פפרז, נו דאוט וסובליים, שלקחו מהם את הערבוב בין סקא, פאנק ורוק. הם היו גם מהלהקות השחורות הבודדות שניגנו רוק כבד באותם ימים, ופתחו את הדרך ללהקות כמו ליבינג קולור (אלבום 615). סרט תיעודי על הלהקה, שיצא ב־2010, סיפר מחדש את הסיפור שלהם, והחזיר אותם לתשומת לב.''',
'''שמעו את Freddie's Dead, ואחריו את המקור של קרטיס מייפילד מ־Superfly (אלבום 246). תשמעו איך שיר סול רך הפך לסערת רוק, ואיך הרוח שלו נשארה.''',
], [
("Freddie's Dead", 'גרסה כבדה ומהירה לשיר של קרטיס מייפילד, עם גיטרות רוק וכלי נשיפה.'),
('Ma and Pa', 'שיר אישי ונוגע על משפחה ועל הורים, עם קצב כבד ושירה רגשית.'),
('Pouring Rain', 'מתחיל רך ונוגה כמו גשם, ומתפרץ לאט לסערה של רוק ונשיפה.'),
])

add(614, [
'''אברית׳ינג בט דה גירל הם טרייסי ת׳ורן ובן וואט, זוג שנפגש באוניברסיטה בעיר האל שבצפון אנגליה. את השם הם לקחו משלט של חנות רהיטים מקומית, שהבטיחה שאפשר לקנות שם "הכל חוץ מהבחורה". בתחילת שנות השמונים, בזמן שרוב הלהקות היו רועשות, הם ניגנו פופ שקט, עם השפעות של ג׳אז, בוסה נובה ושירי קפה. Idlewild, שיצא ב־1988, הוא אלבומם הרביעי, והוא שקט, אינטימי ואישי במיוחד.''',
'''הצליל עדין: גיטרה, פסנתר חשמלי, קלידים רכים, תופים קלים, ומעל הכל הקול של ת׳ורן, נמוך, חם ונקי, בלי שום קישוט. השירים עוסקים בבית, בזוגיות, בזיכרונות ובחלוף הזמן, ונשמעים כמו מכתבים פרטיים. I Always Was Your Girl הוא שיר אהבה רך ופשוט. These Early Days הוא שיר עדין על ילדות מוקדמת ועל הזמן שעובר מהר מדי. Oxford Street הוא שיר נוסטלגי על הנעורים בלונדון. במהדורות מאוחרות נוסף גם I Don't Want to Talk About It, גרסה לשיר של קרייזי הורס, שהפך ללהיט הגדול שלהם באותה תקופה. Shadow on a Harvest Moon ו־Blue Moon Rose שקטים ויפים במיוחד, כמו שירים לסוף הקיץ.''',
'''בשנות התשעים הצמד שינה כיוון לגמרי, ועבר למוזיקה אלקטרונית. השיר Missing, ברמיקס של המפיק טוד טרי, הפך ללהיט עולמי ענק. ת׳ורן שרה גם עם מאסיב אטאק, וואט הפך לתקליטן ולמפיק מוערך, ושניהם כתבו ספרים על חייהם ועל המוזיקה.''',
'''זה אלבום ליום של גשם, לכוס תה ולשקט. שמעו אותו ברצף, בלי למהר, ותנו לקול של ת׳ורן ללוות אתכם. ואם אהבתם, נסו את Treasure של קוקטו טווינס (אלבום 534), צליל שקט אחר מאותן שנים.''',
], [
('I Always Was Your Girl', 'שיר אהבה רך ופשוט, בקול נמוך וחם של טרייסי ת׳ורן, כמעט לחישה.'),
('These Early Days', 'שיר עדין על ילדות מוקדמת ועל הזמן שעובר מהר מדי, בליווי פסנתר רך.'),
('Oxford Street', 'שיר נוסטלגי ושקט על הנעורים בלונדון, ועל מה שנשאר מהם בזיכרון.'),
])

add(615, [
'''ליבינג קולור קמו בניו יורק באמצע שנות השמונים, ובראשם הגיטריסט ורנון ריד, שהיה גם ממייסדי "קואליציית הרוק השחור", ארגון שנאבק בדעה שרוק הוא מוזיקה של לבנים. לצדו ניגנו הזמר קורי גלובר, הבסיסט מאז סקילינגס והמתופף וויל קלהון. מיק ג׳אגר מהרולינג סטונס ראה אותם בהופעה במועדון קטן, התלהב, ועזר להם לקבל חוזה הקלטות. Vivid, אלבום הבכורה, יצא ב־1988.''',
'''המוזיקה מחברת רוק כבד, פאנק, פאנק־רוק, ג׳אז וסול, והגיטרה של ריד מהירה, וירטואוזית ומלאת הפתעות. גלובר שר בקול חזק וגבוה, והקצב של קלהון וסקילינגס גמיש ומדויק. Cult of Personality, הלהיט, בנוי על ריף ענק ושואל איך מנהיגים כריזמטיים שולטים בהמונים, עם קטעי נאומים של מלקולם אקס וג׳ון קנדי. Open Letter (To a Landlord) מוחה נגד גירוש תושבים עניים מהשכונות שלהם. Glamour Boys צוחק על אופנה, ו־Memories Can't Wait הוא גרסה לשיר של טוקינג הדס מ־Fear of Music (אלבום 434). Funny Vibe מתאר את התחושה של אדם שחור שאנשים זרים מתרחקים ממנו ברחוב, וחברי פאבליק אנמי משתתפים בו.''',
'''Cult of Personality זכה בגראמי, והאלבום הפך להצלחה גדולה, דבר נדיר ללהקת רוק שחורה בסוף שנות השמונים. ליבינג קולור הוכיחו שרוק כבד שייך לכולם, והמשיכו את הדרך שפתחו בד בריינס (אלבום 581) ופישבון (אלבום 613). ורנון ריד הפך לאחד הגיטריסטים המוערכים של דורו, והלהקה ממשיכה להופיע ולהקליט עד היום.''',
'''שמעו את Cult of Personality, ושימו לב לסולו של ורנון ריד: מהיר ומשוגע, כמעט כמו ג׳אז. ואחר כך השוו ל־Truth and Soul של פישבון (אלבום 613), שיצא באותה שנה.''',
], [
('Cult of Personality', 'הלהיט, ריף ענק ושאלה חכמה על מנהיגים כריזמטיים, עם סולו מטורף.'),
('Open Letter (To a Landlord)', 'שיר מחאה חזק ונוגע נגד גירוש עניים מהשכונות שלהם, עם שירה עוצמתית.'),
("Memories Can't Wait", 'גרסה סוערת לשיר של טוקינג הדס, עם גיטרות כבדות ומקצב פאנקי.'),
])

add(616, [
'''מאדהאני קמו בסיאטל ב־1988, מתוך שרידי להקה מקומית בשם גרין ריבר, שממנה יצאו גם חברי פרל ג׳אם. הזמר מארק ארם והגיטריסט סטיב טרנר אהבו פאנק מלוכלך, רוק של שנות השישים וגיטרות מעוותות מאוד. השם Superfuzz Bigmuff לקוח משמות של שני דוושות אפקטים לגיטרה, שנותנות את הצליל העבה והמזמזם שלהם. זה בעצם מיני־אלבום קצר, שיצא בחברת התקליטים הקטנה סאב פופ, הבית של סצנת סיאטל.''',
'''הצליל גס, עבה ורועש: גיטרות מעוותות עד הקצה, בס כבד, תופים פרועים, וארם שר וצועק בקול צרוד ומלא בוז. זה רוק שנשמע כאילו הוקלט במוסך, בלי שום ניסיון להיות יפה, ובדיוק בזה הקסם. Touch Me I'm Sick, הסינגל הראשון שלהם, שנכלל במהדורות המורחבות, הפך להמנון של הסצנה. Need מהיר ומלא אנרגיה, Mudride כבד ואיטי כמו בוץ, ו־In 'n' Out of Grace נפתח בדגימה מסרט אופנוענים ישן לפני שהגיטרות נכנסות בכוח. כל השירים קצרים, רועשים ומהירים, ואין בהם רגע אחד מיותר.''',
'''מאדהאני היו מהלהקות הראשונות של הצליל שנקרא אחר כך "גראנג׳", וכמה שנים לפני שנירוונה ופרל ג׳אם כבשו את העולם, הם היו הלהקה הגדולה של סיאטל. הם אף פעם לא הצליחו בגדול כמו חבריהם, אבל ממשיכים לנגן עד היום, באותו צליל מלוכלך ובאותו חוש הומור.''',
'''שמעו את In 'n' Out of Grace בקול רם, וחכו לרגע שבו הגיטרות נכנסות. ואם אהבתם, נסו את You're Living All Over Me של דיינוזאור ג׳וניור (אלבום 586), עוד רעש יפה מאותן שנים.''',
], [
("In 'n' Out of Grace", 'נפתח בדגימה מסרט ישן, ואז הגיטרות נכנסות בכוח ולא עוצרות.'),
('Need', 'שיר מהיר ומלא אנרגיה, עם גיטרות מעוותות ושירה צרודה ומלאת בוז.'),
('Mudride', 'שיר כבד ואיטי כמו בוץ, עם גיטרה שמזמזמת ומתמשכת בלי סוף.'),
])

add(617, [
'''אר.אי.אם כבר הופיעו כאן עם Murmur (אלבום 517) ועם Document (אלבום 589), שהפך אותם ללהקה מצליחה. אחריו הם עזבו את חברת התקליטים הקטנה וחתמו בחברה גדולה, וורנר. Green, שיצא ב־1988, ביום הבחירות לנשיאות בארצות הברית, הוא אלבומם הראשון שם. הוא שמח, צבעוני ומגוון יותר מכל מה שעשו לפני כן, ומלא בתקווה ובפוליטיקה ירוקה, למרות שזה היה סוף שנות רייגן.''',
'''יש כאן שירי פופ קופצניים לצד שירים שקטים עם מנדולינה ואקורדיון. Stand, הלהיט, הוא שיר פופ מטופש ושמח בכוונה, עם שינויי מפתח מצחיקים, שבו סטייפ מבקש מהמאזין לעמוד במקום ולחשוב איפה הוא נמצא. Orange Crush נשמע כמו שיר רוק סוער, אבל מדבר על חייל במלחמת וייטנאם ועל החומר הכימי "אייג׳נט אורנג׳" שפוזר שם. Pop Song 89 צוחק על שירי פופ, ו־World Leader Pretend הוא שיר איטי ויפה על חומות שאנחנו בונים בתוכנו. You Are the Everything הוא שיר שקט ומרגש עם מנדולינה, על ילד ששוכב במושב האחורי של מכונית ומסתכל על הכוכבים. גם Get Up ו־Turn You Inside-Out מראים צד חדש של הלהקה, עם קצב חזק וביטחון גדול.''',
'''Green מכר מיליוני עותקים, ואחריו יצא סיבוב הופעות עולמי ענק, באולמות הגדולים ביותר שבהם ניגנו עד אז. הוא פתח את הדרך ל־Out of Time ול־Losing My Religion, שהפכו אותם לאחת הלהקות הגדולות בעולם בשנות התשעים.''',
'''שמעו את You Are the Everything בשקט, ושימו לב למנדולינה של פיטר באק: היא תחזור בגדול בלהיט הענק שלהם, Losing My Religion. אחר כך שמעו את Stand, כדי לחייך.''',
], [
('Stand', 'שיר פופ שמח ומטופש בכוונה, עם שינויי מפתח מצחיקים ופזמון שנכנס לראש.'),
('Orange Crush', 'שיר רוק סוער שמדבר על חייל במלחמת וייטנאם, עם תופים צבאיים.'),
('You Are the Everything', 'שיר שקט ומרגש עם מנדולינה, על ילד שמסתכל על הכוכבים מהמכונית.'),
])

add(618, [
'''הפי מאנדיז באו מסלפורד, ליד מנצ׳סטר, ובראשם הזמר שון ריידר, בחור של רחוב עם מילים מוזרות, מבולבלות ומצחיקות. לצדו רקד על הבמה בז, חבר שלא ניגן בשום כלי, ורק רקד בטירוף עם מרקס. הלהקה חתמה בחברת פקטורי, החברה של ניו אורדר, ו־Bummed, שיצא ב־1988, הפיק מרטין האנט, המפיק של ג׳וי דיוויז׳ן (אלבומים 435 ו־467). זה היה בדיוק הזמן שבו מוזיקת האסיד האוס, מוזיקת ריקודים אלקטרונית, כבשה את המועדונים של מנצ׳סטר.''',
'''הצליל עכור, מסטולי ומלא גרוב: בס עמוק ומתגלגל, גיטרה פאנקית, קלידים מוזרים ותופים שמזכירים מוזיקת מועדונים. ריידר לא באמת שר, אלא מדבר, ממלמל וצועק על דמויות מוזרות, על עבירות קטנות ועל לילות ארוכים. Wrote for Luck, הסינגל, הפך מאוחר יותר ללהיט ריקודים ברמיקס. Mad Cyril נפתח בדגימה מסרט, Lazyitis מתנודד ועייף, ו־Moving in with קצבי ומלא אנרגיה מטורפת. יש באלבום תחושה של מסיבה שנמשכת יותר מדי, בשעה שבע בבוקר.''',
'''Bummed הוא אחד האלבומים שפתחו את סצנת "מאדצ׳סטר", שבה רוק ומוזיקת ריקודים אלקטרונית התחברו, יחד עם הסטון רוזס (אלבום 646). הפי מאנדיז הפכו בשנים הבאות לכוכבים בבריטניה, ושון ריידר הפך לדמות אגדית ושערורייתית של התרבות הבריטית. בשנים שאחרי הם זכו להצלחה גדולה עוד יותר, עם להיטים כמו Step On ו־Kinky Afro.''',
'''זה אלבום מוזר, ולא קל בהאזנה ראשונה. תנו לבס להוביל אתכם ואל תנסו להבין את המילים. ואחר כך שמעו את Technique של ניו אורדר (אלבום 638), חבריהם לחברת התקליטים מאותה תקופה.''',
], [
('Wrote for Luck', 'הסינגל, גרוב עכור וממכר, שהפך מאוחר יותר ללהיט ריקודים ברמיקס.'),
('Lazyitis', 'שיר מתנודד ועייף, כמו בוקר אחרי מסיבה ארוכה מדי, עם בס מתגלגל.'),
('Moving in With', 'שיר קצבי ומלא אנרגיה מטורפת, עם גיטרה פאנקית ושירה צועקת.'),
])

add(619, [
'''הגו־ביטווינס באו מבריסביין שבאוסטרליה, ובמרכזם שני כותבים שהיו חברים קרובים: רוברט פוסטר וגרנט מקלנן. כל אחד מהם כתב ושר את השירים שלו, בסגנון אחר: פוסטר זוויתי, מוזר ושנון יותר, ומקלנן רומנטי, מלודי ורך. 16 Lovers Lane, שיצא ב־1988, הוא אלבומם השישי, והאחרון לפני שנפרדו לשנים ארוכות. באותם ימים בלהקה ניגנו גם המתופפת לינדי מוריסון והכנרת אמנדה בראון, ובאוויר היו כמה סיפורי אהבה בין חברי הלהקה, שנשמעים היטב בשירים.''',
'''הצליל בהיר, אקוסטי וחם: גיטרות מצלצלות, כינור, אבוב, קולות רקע רכים ותופים קלים. זה פופ עדין, כמו בוקר קיץ באוסטרליה, אבל המילים עצובות ומלאות כאב של אהבות שנגמרו. Streets of Your Town של מקלנן הוא שיר קיץ קליל ושמח, שמסתיר בתוכו שורה קשה על אלימות בבתים שבעיר. Was There Anything I Could Do? הוא שאלה כואבת אחרי פרידה. Love Goes On! מתוק ואופטימי, ו־Quiet Heart הוא שיר שקט ויפה, כמו לחישה. Dive for Your Memory, הסוגר, הוא פרידה רכה מאהבה ומתקופה.''',
'''האלבום לא הצליח מסחרית, אבל נחשב היום לאחד האלבומים האוסטרליים היפים ביותר. מקלנן מת ב־2006, וכמה שנים אחר כך נקרא על שם הלהקה גשר חדש בבריסביין, "גשר הגו־ביטווינס". Streets of Your Town נחשב באוסטרליה לאחד השירים האהובים של כל הזמנים.''',
'''שמעו את Streets of Your Town, ושימו לב למילים: שיר קיץ קליל, עם שורה אחת אפלה באמצע. ואחר כך שמעו את Calenture של הטריפידס (אלבום 605), עוד להקה אוסטרלית מאותן שנים, עם צליל אחר לגמרי.''',
], [
('Streets of Your Town', 'שיר קיץ קליל ושמח של מקלנן, שמסתיר בתוכו שורה אחת קשה ואפלה.'),
('Was There Anything I Could Do?', 'שאלה כואבת אחרי פרידה, עם גיטרה מצלצלת ושירה שבורה ועדינה.'),
('Quiet Heart', 'שיר שקט ויפה כמו לחישה, עם כלי מיתר רכים ומילים עדינות.'),
])

add(620, [
'''קאובוי ג׳אנקיז הם להקה משפחתית מטורונטו שבקנדה: האחים מייקל ופיטר טימינס, אחותם מרגו, שהיא הזמרת, והבסיסט אלן אנטון. The Trinity Session, שיצא ב־1988, הוקלט ביום אחד, נובמבר 1987, בכנסייה בטורונטו, עם מיקרופון אחד בלבד שהוצב באמצע החדר, והנגנים עמדו מסביבו. כך נקלטו גם ההד של הכנסייה, הנשימות והשקט שבין הצלילים. ההקלטה עלתה כמה מאות דולרים בלבד.''',
'''המוזיקה איטית מאוד, שקטה ומהפנטת: גיטרות, מפוחית, כינור, אקורדיון ותופים שבקושי נוגעים בתוף. מרגו טימינס שרה בקול רך, נמוך ורגוע, כמעט לוחש, כמו מישהי ששרה לעצמה בשעה מאוחרת בלילה. יש כאן שירים מקוריים לצד שירי קאנטרי ובלוז ישנים. Sweet Jane, השיר של הוולווט אנדרגראונד מ־Loaded, מושר כאן כמו שיר ערש, ולו ריד אמר שזו הגרסה האהובה עליו. I'm So Lonesome I Could Cry של האנק וויליאמס נשמע עצוב מתמיד. Misguided Angel, שיר מקורי, מספר על בחורה שמתאהבת בבחור לא מתאים, ו־Mining for Gold, הפותח, מושר בלי שום ליווי. הקצב כמעט לא משתנה לאורך כל האלבום, וזה יוצר תחושה של שקט עמוק, כמו נסיעה ארוכה בלילה.''',
'''האלבום הפך להצלחה מפתיעה, ופתח את הדרך לזרם של קאנטרי שקט ואלטרנטיבי. הוא מוכיח שלפעמים מיקרופון אחד, חדר טוב ונגנים שמקשיבים זה לזה מספיקים כדי לעשות קסם. גם אחרי עשרות שנים, הם ממשיכים להופיע ולהקליט באותו הרכב משפחתי.''',
'''שמעו את האלבום בלילה, בחושך, בווליום נמוך. ואחר כך שמעו את Sweet Jane בגרסה של הוולווט אנדרגראונד, כדי לשמוע כמה שיר אחד יכול להשתנות.''',
], [
('Sweet Jane', 'שיר של הוולווט אנדרגראונד שהפך לשיר ערש איטי, ולו ריד אהב במיוחד.'),
('Misguided Angel', 'שיר מקורי ויפה על בחורה שמתאהבת בבחור לא מתאים, בקול רגוע.'),
('Mining for Gold', 'הפותח, שיר פועלים ישן שמרגו שרה לבד, בלי שום ליווי, בהד הכנסייה.'),
])

add(621, [
'''טרייסי צ׳פמן גדלה בקליבלנד שבאוהיו, אצל אם יחידה, ולמדה אנתרופולוגיה באוניברסיטת טאפטס ליד בוסטון. בזמן הלימודים היא הופיעה בבתי קפה וברחובות עם גיטרה אקוסטית, ובן כיתה, שאביו היה בעל חברת פרסום מוזיקלית, הביא אותה לחברת תקליטים. אלבום הבכורה שלה יצא ב־1988, בזמן שהפופ היה מלא בסינתיסייזרים ובשיער גדול, והפך בבת אחת להצלחה עצומה.''',
'''הצליל פשוט: גיטרה אקוסטית, בס, תופים קלים, וקול עמוק, נמוך ושקט שנשמע כמעט כמו קול של גבר. המילים מדברות על עוני, גזענות, אלימות במשפחה וחלומות לברוח. Fast Car הוא סיפור של אישה צעירה שעובדת בחנות, מטפלת באבא שמשתה, וחולמת לברוח עם החבר שלה במכונית מהירה, לחיים טובים יותר, והוא אחד השירים המרגשים של שנות השמונים. Talkin' 'bout a Revolution מבטיח שהעניים יקומו יום אחד. Baby Can I Hold You הוא שיר אהבה שקט על מילים שקשה להגיד, ו־Behind the Wall מושר בלי שום ליווי, ומתאר אישה שומעת אלימות מאחורי הקיר של השכנים, והמשטרה לא מגיעה.''',
'''צ׳פמן הופיעה ב־1988 בקונצרט ענק לכבוד יום הולדתו השבעים של נלסון מנדלה, שעוד היה אז בכלא, והופעה פשוטה שלה עם גיטרה בלבד הפכה אותה לכוכבת. האלבום זכה בשלושה פרסי גראמי ומכר מיליוני עותקים. ב־2023 Fast Car חזר למצעדים בגרסת קאנטרי של לוק קומבס, וצ׳פמן הייתה האישה השחורה הראשונה שזכתה בפרס לשיר השנה של מוזיקת הקאנטרי.''',
'''שמעו את Fast Car עד הסוף, והקשיבו לסיפור: הוא נבנה לאט, משיר תקווה לשיר של אכזבה. ואחר כך שמעו את Behind the Wall, שאין בו שום כלי.''',
], [
('Fast Car', 'סיפור של אישה צעירה שחולמת לברוח לחיים טובים יותר, אחד השירים המרגשים של העשור.'),
("Talkin' 'bout a Revolution", 'שיר מחאה שקט ונחוש, שמבטיח שהעניים יקומו יום אחד ויתבעו את שלהם.'),
('Behind the Wall', 'שיר בלי שום ליווי, על אלימות שנשמעת מאחורי הקיר והמשטרה שלא מגיעה.'),
])

add(622, [
'''מיי בלאדי ולנטיין היא להקה אירית שעברה ללונדון, ובמרכזה הגיטריסט והזמר קווין שילדס והזמרת והגיטריסטית בלינדה בוצ׳ר, לצד המתופף קולם או׳סיוסויג והבסיסטית דבי גוג׳. בשנים הראשונות הם ניגנו פופ־גיטרות רגיל למדי, ואז, בסוף שנות השמונים, שילדס מצא צליל חדש לגמרי. Isn't Anything, שיצא ב־1988 בחברת קריאיישן, הוא אלבום הבכורה באורך מלא, והוקלט במהירות בוויילס, בכמה שבועות עם מעט מאוד שינה.''',
'''הסוד הוא הגיטרה: שילדס מנגן ומזיז כל הזמן את ידית הוויברטו של הגיטרה, כך שהצלילים מתעקמים, צפים ומתנדנדים, כאילו מישהו מותח את הקלטת. מעל הקיר הזה של צליל, שילדס ובוצ׳ר שרים בלחישה, חצי ישנים, והמילים כמעט לא נשמעות. זה נשמע כמו חלום, קצת מבולבל וקצת מסוכן. Soft as Snow (But Warm Inside) פותח בתופים חזקים ובגיטרה מעוקמת. Feed Me with Your Kiss מהיר ורועש, You Never Should ממכר ועצבני, ו־Lose My Breath שקט ונושם, כמעט אקוסטי. Several Girls Galore ו־Nothing Much to Lose מראים כמה מגוון האלבום, בין רעש לבין שקט.''',
'''Isn't Anything היה האלבום שהגדיר את הסגנון שנקרא "שוגייז", יחד עם Psychocandy של הג׳יזס אנד מרי צ׳יין (אלבום 559), והוביל לאלבום הבא שלהם, Loveless, שנחשב לאחד האלבומים הגדולים של שנות התשעים. להקות רבות מנסות עד היום לחקות את הצליל של שילדס, ומעטות מצליחות.''',
'''שמעו את האלבום עם אוזניות, בווליום גבוה, ותנו לגיטרות לעטוף אתכם. אל תנסו להבין את המילים: הן חלק מהצליל, כמו עוד כלי. התחילו ב־Lose My Breath ואחר כך עברו ל־Feed Me with Your Kiss.''',
], [
('Soft as Snow (But Warm Inside)', 'הפותח, תופים חזקים וגיטרה מעוקמת, ושירה לוחשת כמו בחלום מוזר.'),
('Feed Me with Your Kiss', 'שיר מהיר ורועש, עם גיטרות מתעקמות ופזמון שחוזר וחוזר.'),
('Lose My Breath', 'שיר שקט ונושם, כמעט אקוסטי, שבו הלחישה של בלינדה בוצ׳ר מובילה.'),
])

add(623, [
'''הפיקסיז באו מבוסטון, והמנהיג שלהם, בלאק פרנסיס, למד ספרדית בפוארטו ריקו כסטודנט בחילופי סטודנטים, וחזר משם עם שירים מוזרים ומילים בספרדית. לצדו ניגנו הבסיסטית והזמרת קים דיל, הגיטריסט ג׳ואי סנטיאגו והמתופף דייוויד לאברינג. Surfer Rosa, אלבום הבכורה באורך מלא, יצא ב־1988 בחברת 4AD הבריטית, אחרי ת׳רואינג מיוזס (אלבום 576), והקליט אותו סטיב אלביני מביג בלאק (אלבום 553), בצליל גולמי, חד וישיר.''',
'''הסוד של הפיקסיז הוא המעבר בין שקט לרעש: הבתים שקטים, עם בס פשוט וגיטרה מתגנבת, ואז הפזמון מתפוצץ בצעקות ובגיטרות. פרנסיס צועק, ממלמל ושר על דברים מוזרים: מוטציות, תנ״ך, סקס וסוריאליזם, וקים דיל עונה לו בקול מתוק ורגוע. Where Is My Mind? נבנה לאט על גיטרה פשוטה וקולות "אוווו", ומתאר צלילה בים שבה הראש מתנתק מהגוף. Gigantic, שקים דיל כתבה יחד עם פרנסיס ושרה, הוא שיר אהבה מוזר ומלא אור. Bone Machine פותח בתופים חזקים, ו־Vamos ו־Oh My Golly! שרים בספרדית.''',
'''האלבום השפיע מאוד על הרוק של שנות התשעים. קורט קוביין מנירוונה סיפר שכשכתב את Smells Like Teen Spirit, הוא ניסה בעצם לחקות את הפיקסיז. Where Is My Mind? זכה לחיים חדשים ב־1999, בסוף הסרט "מועדון קרב". הלהקה התפרקה ב־1993, אבל חזרה להופיע ב־2004, והיא פעילה עד היום.''',
'''שמעו את Where Is My Mind?, ואחריו את Gigantic: פרנסיס וקים, השניים שהפכו את הפיקסיז לייחודיים. ואחר כך נסו את Daydream Nation של סוניק יות׳ (אלבום 630), שיצא באותה שנה.''',
], [
('Where Is My Mind?', 'גיטרה פשוטה וקולות "אוווו", ושיר מוזר על ראש שמתנתק מהגוף בזמן צלילה.'),
('Gigantic', 'השיר שקים דיל שרה, שיר אהבה מוזר, מתוק ומלא אור עם בס מוביל.'),
('Bone Machine', 'הפותח, תופים חזקים וגיטרה צורמת, שקט ורעש שמתחלפים בבת אחת.'),
])

add(624, [
'''מטאליקה כבר הופיעו כאן עם Master of Puppets (אלבום 567). אחרי מותו של הבסיסט קליף ברטון, הם צירפו את ג׳ייסון ניוסטד, ו־...And Justice for All, שיצא ב־1988, הוא האלבום הראשון שלו איתם. בגלל הדרך שבה האלבום נמהל, הבס כמעט לא נשמע בו בכלל, ועד היום מעריצים מתווכחים אם זה היה מכוון. האלבום עוסק בצדק, בשחיתות, בצנזורה ובמלחמה, ועל העטיפה מופיע פסל של אלת הצדק, מכוסה בחבלים ונסדקת.''',
'''השירים ארוכים ומסובכים עוד יותר מבאלבום הקודם, עם שינויי קצב רבים, ריפים טכניים וחלקים שנמתחים לעשר דקות. הצליל יבש, חד וקר, עם תופים חזקים מאוד. One, השיר המפורסם באלבום, מבוסס על ספר על חייל שנפגע במלחמת העולם הראשונה ואיבד את ידיו, רגליו, ראייתו ודיבורו, והוא כלוא בתוך גופו. השיר מתחיל רך ועצוב, עם גיטרות נקיות, ומסתיים בסערה של מכות תופים כמו מקלעים. Blackened פותח על חורבן הכדור הארץ, Harvester of Sorrow כבד ואיטי, ו־To Live Is to Die הוא קטע כלי שמשתמש בריפים שהשאיר אחריו קליף ברטון. The Shortest Straw ו־Eye of the Beholder מתארים עולם שבו כולם חשודים, והצדק עיוור באמת.''',
'''One היה הקליפ הראשון של מטאליקה, וזכה בפרס הגראמי הראשון שלהם. האלבום הגיע למקום השישי במצעד האמריקאי, ופתח את הדרך לאלבום הבא שלהם, "האלבום השחור", שהפך אותם לאחת הלהקות הגדולות בעולם.''',
'''שמעו את One עד הסוף: שבע דקות שמתחילות כבלדה ונגמרות בסערה. ושימו לב לבס, או ליתר דיוק לכך שכמעט אי אפשר לשמוע אותו.''',
], [
('One', 'שיר על חייל שכלוא בגופו אחרי המלחמה, מבלדה עצובה לסערה של מקלעים.'),
('Blackened', 'הפותח, ריף מהיר וחד על חורבן הכדור הארץ, עם שינויי קצב רבים.'),
('Harvester of Sorrow', 'שיר כבד ואיטי עם ריף ענק, שקל יחסית להיכנס אליו.'),
])

add(625, [
'''דיינוזאור ג׳וניור כבר הופיעו כאן עם You're Living All Over Me (אלבום 586). Bug, שיצא ב־1988, הוא האלבום השלישי שלהם, והאחרון בהרכב המקורי. היחסים בין ג׳יי מאסקיס, שכתב כמעט את כל השירים, לבין הבסיסט לו בארלו היו גרועים מאוד, והשניים כמעט לא דיברו זה עם זה. זמן קצר אחרי שהאלבום יצא, מאסקיס פשוט הודיע שהלהקה התפרקה, ואז המשיך בלי בארלו. כל המתח הזה נשמע באלבום.''',
'''כאן מאסקיס כבר לא מסתיר את המנגינות: השירים בנויים כמו שירי פופ, עם פזמונים ברורים, אבל הגיטרה שלו עדיין רועשת, מלאה פאז ומעוותת, והסולואים ארוכים ופרועים. הוא שר בקול עייף, מנומנם ומתוק, על אהבה, על בלבול ועל חוסר היכולת לתקשר עם אנשים. Freak Scene, הפותח, הוא אחד השירים האהובים של הרוק האלטרנטיבי: שיר על ידידות מסובכת, עם גיטרה אקוסטית שהופכת לסערה. No Bones שקט ועצוב, They Always Come קצבי וכבד, ו־Budge קצר ומהיר. Don't, הסוגר, הוא צעקה ארוכה וכואבת של בארלו, שחוזר שוב ושוב על שאלה אחת: למה אתה לא אוהב אותי?''',
'''Bug היה האלבום שבו דיינוזאור ג׳וניור הפכו ללהקה המובילה של הרוק העצמאי האמריקאי, רגע לפני שנירוונה וסיאטל כבשו את העולם. בארלו הקים את סבאדו ואת פולק אימפלוז׳ן, ומאסקיס הפך לאחד מגיבורי הגיטרה של דורו. ב־2005 השלושה חזרו לנגן יחד, ומאז הם מוציאים אלבומים חדשים.''',
'''שמעו את Freak Scene, ושימו לב איך שיר פופ קטן מתפוצץ פתאום לסולו גיטרה פרוע. ואם אתם רוצים להבין את המתח בלהקה, שמעו את Don't עד הסוף, אם תוכלו.''',
], [
('Freak Scene', 'הפותח והאהוב, שיר על ידידות מסובכת עם גיטרה אקוסטית שהופכת לסערה.'),
('No Bones', 'שיר שקט ועצוב, עם מנגינה יפה וקול עייף ומתוק של מאסקיס.'),
('They Always Come', 'שיר קצבי וכבד, עם גיטרה מעוותת וסולו ארוך ופרוע במיוחד.'),
])

add(626, [
'''דגמר קראוזה היא זמרת גרמנייה מהמבורג, שהתחילה לשיר בגיל צעיר במועדונים של העיר, ואחר כך התפרסמה בלהקות ניסיוניות בריטיות כמו סלאפ האפי והנרי קאו. הנס אייזלר, שהשירים שלו ממלאים את האלבום, היה מלחין ממוצא יהודי שגדל בווינה, תלמידו של ארנולד שנברג ושותפו הקרוב של המחזאי ברטולט ברכט. הוא ברח מהנאצים לאמריקה, ואחרי המלחמה גורש משם בגלל דעותיו הקומוניסטיות, וחי במזרח גרמניה. Tank Battles יצא ב־1988, בשתי גרסאות: אחת באנגלית ואחת בגרמנית.''',
'''השירים קצרים, חדים ותיאטרליים, כמו שירי קברט מהשנים שבין שתי מלחמות העולם. הליווי פשוט: פסנתר, מעט כלי נשיפה, אקורדיון, ולפעמים רק קול וקצב. הקול של קראוזה גבוה, חד ולפעמים צורם, והיא שרה בזעם, באירוניה ובכאב, כמו שחקנית בהצגה. השירים עוסקים במלחמה, בעוני, בעבודה, בניצול ובחיים תחת משטרים קשים, ורבים מהם נכתבו על מילים של ברכט. יש כאן שירי מחאה של פועלים, שירים סאטיריים על בנקים ועל כסף, ושירים נוגים של גלות ממולדת.''',
'''האלבום החזיר את השירים של אייזלר לקהל צעיר, בתקופה שבה רבים כבר שכחו אותם. הוא מראה שמוזיקה שנכתבה לפני חמישים שנה יכולה להישמע חדה ורלוונטית כמו כל להקת פאנק, אם שרים אותה בכעס ובכנות.''',
'''זה אלבום לשמיעה עם תשומת לב, כמו הצגת תיאטרון. אם הוא נשמע מוזר בהתחלה, שמעו כמה שירים ותנו לקול של קראוזה להוביל אתכם לתוך העולם הקודר והמצחיק שלו.''',
], [
('The Song of the Whitewash', 'שיר סאטירי חד על אנשים שמנסים לצבוע בלבן קירות שמתפוררים, על מילים של ברכט.'),
('Bankenlied', 'שיר קברט ציני ומצחיק על בנקים ועל כסף, בגרמנית ובשירה חדה ותיאטרלית.'),
('Mankind', 'שיר קצר ונוקב על בני האדם ועל מה שהם עושים זה לזה.'),
])

add(627, [
'''קיי.די. לאנג גדלה בעיירה קטנה במחוז אלברטה שבקנדה, ובתחילת דרכה הופיעה עם להקה פרועה, עם שיער קצוץ, משקפיים בלי עדשות ומגפי בוקרים, כמחווה משועשעת לזמרת פטסי קליין. Shadowland, שיצא ב־1988, הוא אלבום אחר לגמרי: הוא הוקלט בנאשוויל עם המפיק הוותיק אוון בראדלי, שהפיק בשנות החמישים והשישים את פטסי קליין עצמה. בראדלי, שכבר פרש, חזר לאולפן במיוחד בשבילה, והביא איתו נגנים ותיקים מתקופת הזהב של הקאנטרי.''',
'''המוזיקה היא קאנטרי קלאסי ומלוטש, עם כלי מיתר, פסנתר, גיטרת סטיל, מקהלות רקע וקצב איטי ורך, כמו בתקליטים של שנות החמישים. לאנג שרה בקול עמוק, עשיר וגמיש, שנע בקלות בין לחישה לשירה רחבה ומלאה, ורבים השוו אותו לקולה של פטסי קליין. רוב השירים הם שירי קאנטרי ופופ ישנים, שהיא בחרה בקפידה. I Wish I Didn't Love You So הוא בלדה כואבת ויפה. Black Coffee הוא שיר ג׳אז לילי ועצוב. Honky Tonk Angels Medley הוא מחרוזת שבה מצטרפות אליה שלוש זמרות קאנטרי מיתולוגיות: לורטה לין, קיטי וולס וברנדה לי.''',
'''Shadowland הציג את לאנג כאחד הקולות הגדולים של דורה. בהמשך היא התרחקה מהקאנטרי, הצליחה מאוד עם הלהיט Constant Craving, והייתה מהכוכבות הראשונות בצפון אמריקה שסיפרו בגלוי שהן לסביות. הגרסה שלה ל־Hallelujah של לאונרד כהן נחשבת לאחת היפות שהוקלטו.''',
'''שמעו את I Wish I Didn't Love You So באור עמום, ושימו לב לשליטה של לאנג בקול: היא יודעת מתי ללחוש ומתי לפתוח את הקול עד הסוף. ואחר כך שמעו את Don't Come Home a Drinkin' של לורטה לין (אלבום 102).''',
], [
("I Wish I Didn't Love You So", 'בלדה כואבת ויפה, שבה לאנג מראה את השליטה המלאה שלה בקול.'),
('Black Coffee', 'שיר ג׳אז לילי ועצוב על המתנה לאהוב שלא חוזר, עם פסנתר רך.'),
('Honky Tonk Angels Medley', 'מחרוזת עם שלוש זמרות קאנטרי מיתולוגיות, לורטה לין, קיטי וולס וברנדה לי.'),
])

add(628, [
'''אמריקן מיוזיק קלאב באו מסן פרנסיסקו, ובמרכזם עמד הזמר וכותב השירים מארק אייצל, אחד הכותבים העצובים והכנים של הרוק האמריקאי. בהופעות הוא היה לפעמים שיכור, בוכה או כועס על הקהל, ולפעמים מרגש עד דמעות. California, שיצא ב־1988, הוא אלבומם השלישי, והוא שקט ונוגה יותר מקודמיו. מבקרים התאהבו בלהקה, אבל כמעט אף אחד לא קנה את התקליטים, וזה הפך לחלק מהסיפור שלהם.''',
'''המוזיקה עדינה ושקופה: גיטרות אקוסטיות וחשמליות נקיות, גיטרת פדל סטיל שנשמעת כמו בכי רחוק, ותופים שקטים. השירים עוסקים בבדידות, באלכוהול, באהבה שנכשלה ובחברים שהלכו, והם נכתבו בתקופה שבה מגפת האיידס הכתה קשה בסן פרנסיסקו, והעצב של העיר נשמע בהם. Firefly הוא שיר שקט ויפה, Laughingstock מר ומצחיק, ו־Bad Liquor הוא רוק מחוספס על שתייה. Western Sky ו־Blue and Grey Shirt הם שירים שקטים ונוגעים, כמו שיחה בלילה עם חבר. Last Harbor הוא שיר שקט ונוגה במיוחד, כמו סירה אחרונה שעוזבת את הנמל.''',
'''האלבום לא נמכר, אבל עם השנים הוא נחשב לאחד היפים של הרוק האמריקאי העצמאי, ואייצל זכה להערכה גדולה מכותבי שירים אחרים. כתב העת רולינג סטון בחר בו ב־1991 לכותב השירים של השנה, ולהקות רבות של שנות התשעים, שנקראו "סלוקור", הושפעו מהצליל השקט והעצוב של הלהקה. אייצל המשיך לכתוב ולהופיע גם בקריירת סולו, ומעריציו המעטים אך הנאמנים רואים בו גאון שלא קיבל את מה שהגיע לו.''',
'''זה אלבום ללילה, לשקט ולמחשבות. שמעו אותו לבד, עם אוזניות. ואם אהבתם, נסו את The Trinity Session של קאובוי ג׳אנקיז (אלבום 620), עוד אלבום שקט ונוגה מאותה שנה.''',
], [
('Firefly', 'שיר שקט ויפה כמו גחלילית בלילה, עם גיטרה עדינה וקול שבור.'),
('Laughingstock', 'שיר מר ומצחיק על אדם שהפך לבדיחה בעיני כולם, עם פדל סטיל.'),
('Western Sky', 'שיר שקט ונוגע כמו שיחה בלילה, עם גיטרה אקוסטית ושמיים פתוחים.'),
])

add(629, [
'''הסמית׳ס התפרקו ב־1987, רגע לפני שיצא Strangeways, Here We Come (אלבום 598), ומוריסי נשאר בלי ג׳וני מאר, השותף שכתב את כל המוזיקה. אחרי חודשים ספורים בלבד הוא נכנס לאולפן עם המפיק סטיבן סטריט, שעבד עם הסמית׳ס, ועם הגיטריסט ויני ריילי מלהקת דורוטי קולאם. Viva Hate, אלבום הסולו הראשון שלו, יצא ב־1988, והגיע מיד למקום הראשון במצעד הבריטי. הוא הוכיח שמוריסי יכול להצליח גם לבד.''',
'''הצליל רך ונקי יותר מזה של הסמית׳ס: גיטרות מצלצלות, כלי מיתר, קלידים, ומוריסי שר בקול המוכר שלו, מלא בהומור עצוב, בגעגועים ובבדידות. Suedehead, הסינגל הראשון, הוא שיר קליל ומהיר על אהבה מעיקה. Everyday Is Like Sunday מתאר עיירת חוף אנגלית אפורה מחוץ לעונה, שבה כל יום נראה כמו יום ראשון משעמם, והוא אחד השירים היפים ביותר שכתב. Late Night, Maudlin Street הוא שיר ארוך ונוסטלגי על ילדות בשכונה ענייה במנצ׳סטר. Alsatian Cousin פותח ברעש של גיטרות, ו־Margaret on the Guillotine, הסוגר, הוא שיר סאטירי חריף נגד ראש הממשלה מרגרט ת׳אצ׳ר.''',
'''האלבום פתח קריירת סולו ארוכה ומצליחה, שבה מוריסי נשאר דמות אהובה ושנויה במחלוקת גם יחד. Everyday Is Like Sunday ו־Suedehead נשארו מהשירים המוכרים ביותר שלו, ואמנים רבים ביצעו אותם. אחרי שנים של הצלחה, התבטאויות פוליטיות שלו גרמו לרבים להתרחק ממנו, אבל השירים מהתקופה הזו נשארו אהובים.''',
'''שמעו את Everyday Is Like Sunday, ודמיינו טיילת ריקה בגשם. ואחר כך שמעו את There Is a Light That Never Goes Out מ־The Queen Is Dead (אלבום 583), כדי לשמוע מה מוריסי השאיר מאחור.''',
], [
('Everyday Is Like Sunday', 'תיאור עצוב ויפה של עיירת חוף אפורה מחוץ לעונה, עם כלי מיתר.'),
('Suedehead', 'הסינגל הראשון, שיר קליל ומהיר על אהבה מעיקה, עם גיטרה מצלצלת.'),
('Late Night, Maudlin Street', 'שיר ארוך ונוסטלגי על ילדות בשכונה ענייה במנצ׳סטר, כמו יומן אישי.'),
])

add(630, [
'''Daydream Nation, שיצא ב־1988, הוא האלבום שבו סוניק יות׳ הגיעו לשיא. אחרי EVOL (אלבום 574) ו־Sister (אלבום 604), הלהקה הקליטה אלבום כפול, ארוך ושאפתני, שנשמע כמו מפה של כל מה שהם יודעים לעשות. זה היה האלבום האחרון שלהם בחברת תקליטים עצמאית, לפני שעברו לחברה גדולה. על העטיפה מופיע ציור של נר דולק של הצייר הגרמני גרהרד ריכטר, ובפנים יש מוזיקה שנשמעת כמו להבה: חמה, רועדת ומסוכנת.''',
'''השירים ארוכים, עם חלקים של שירה ופזמונים, ואז קטעים ארוכים שבהם הגיטרות של ת׳רסטון מור ולי רנאלדו נבנות, מתנגשות ומתפוצצות. Teen Age Riot, הפותח, הוא אחד השירים הגדולים של הרוק האלטרנטיבי: אחרי פתיחה שקטה עם קולה של קים גורדון, הוא פורץ לשיר רוק מהיר ושמח, על נשיא דמיוני של אמריקה, בהשראת ג׳יי מאסקיס מדיינוזאור ג׳וניור. Silver Rocket מהיר ומלא רעש. The Sprawl, שגורדון שרה, הושפע מספרי מדע בדיוני. Eric's Trip ו־Hey Joni הם שירים של לי רנאלדו, ו־Candle ו־Kissability מלאים באנרגיה. האלבום מסתיים בטרילוגיה, שלושה חלקים ארוכים שזורמים זה לתוך זה.''',
'''Daydream Nation נבחר לארכיון ההקלטות הלאומי של ספריית הקונגרס האמריקאית, ונחשב לאחד האלבומים החשובים של שנות השמונים. הוא הראה שרוק רועש וניסיוני יכול להיות גם יפה, מרגש ומלא שמחה. גם להקות רבות של הדור הבא, כמו נירוונה, ראו בסוניק יות׳ אחים גדולים, ונעזרו בהם בדרך להצלחה.''',
'''זה אלבום ארוך, אז שמעו אותו בשני חלקים. התחילו ב־Teen Age Riot, שמתחיל בשקט ומתפוצץ, ואחר כך תנו לגיטרות לקחת אתכם.''',
], [
('Teen Age Riot', 'הפותח, שקט שפורץ לרוק מהיר ושמח, על נשיא דמיוני של אמריקה.'),
('Silver Rocket', 'שיר מהיר ומלא רעש, שבאמצעו נפתח לקטע ארוך של גיטרות מתנגשות.'),
('The Sprawl', 'שיר של קים גורדון בהשראת מדע בדיוני, נבנה לאט לסערה של גיטרות.'),
])

add(631, [
'''הסוגרקיובס קמו ברייקיאוויק שבאיסלנד ב־1986, מתוך חבורת משוררים, אמנים ומוזיקאים פאנקיסטים, ובמרכזם הזמרת הצעירה ביורק גודמונדסדוטיר, שכבר הקליטה אלבום ילדים בגיל אחת־עשרה. השם, "קוביות סוכר", נבחר כבדיחה. הסינגל הראשון שלהם, Birthday, הפך ללהיט מחתרתי בבריטניה, ו־Life's Too Good, שיצא ב־1988, היה אלבום הבכורה, והאלבום האיסלנדי הראשון שזכה להצלחה בינלאומית גדולה.''',
'''הצליל הוא פוסט־פאנק קופצני ומשוגע, עם גיטרות חדות, בס קופץ, תופים קצביים וחצוצרה. אבל במרכז עומד הקול של ביורק: גבוה, חזק, פראי ומשתנה כל הזמן, צועק, לוחש, צוחק ונוהם. לצדה צועק ומדבר החבר איינאר אורן, בקולות מוזרים ומצחיקים. Birthday הוא שיר מוזר ויפה על ילדה בת חמש שמאוהבת בשכן שלה, והקול של ביורק מתרומם בו כמו ציפור. Motorcrash מהיר ופאנקי, Delicious Demon קופצני ושובב, ו־Deus הוא שיר משועשע ומוזר על אלוהים ועל אמונה, עם קולות שמתווכחים. Coldsweat כבד ומאיים, ו־Mama הוא שיר מוזר על אם ועל לידה, עם קולות שקופצים מצד לצד.''',
'''הסוגרקיובס התפרקו ב־1992, וביורק פתחה בקריירת סולו שהפכה אותה לאחת האמניות המקוריות והמשפיעות בעולם. אבל כבר כאן, באלבום הראשון, שומעים את הקול שלה בכל עוצמתו, ואת השמחה הפרועה של חבורה איסלנדית שמגלה את העולם. האלבום פתח את הדלת לאיסלנד כולה, ולהקות ואמנים רבים משם הלכו בדרך שהם סללו.''',
'''שמעו את Birthday, ושימו לב לרגע שבו הקול של ביורק מתרומם ומשתחרר. אחר כך שמעו את Motorcrash, כדי לשמוע את הצד הפאנקי של הלהקה. שימו לב לחצוצרה של איינאר אורן: היא קצרה, אבל מוסיפה ללהקה טעם מיוחד.''',
], [
('Birthday', 'שיר מוזר ויפה על ילדה בת חמש שמאוהבת בשכן, והקול של ביורק עף.'),
('Motorcrash', 'שיר מהיר ופאנקי על תאונה, עם גיטרות חדות וצעקות משמחות.'),
('Deus', 'שיר משועשע ומוזר על אלוהים ועל אמונה, בקצב קופצני ועם קולות שמתווכחים.'),
])

add(632, [
'''דווייט יואקם נולד בקנטקי, גדל באוהיו, ועבר ללוס אנג׳לס, שם ניגן קאנטרי במועדוני פאנק ורוק, בזמן שנאשוויל סירבה להקשיב לו. הוא אהב את "צליל בייקרספילד", הקאנטרי החד והחשמלי של באק אוונס (אלבום 47) ומרל האגארד (אלבום 99), ולא את הקאנטרי המלוטש של שנות השמונים. Buenas Noches from a Lonely Room, שיצא ב־1988, הוא אלבומו השלישי, ואת כולו הפיק הגיטריסט פיט אנדרסון, שותפו הקבוע.''',
'''הצליל הוא קאנטרי חשמלי של בארים: גיטרה טלקסטר חדה ומצלצלת, גיטרת סטיל, בס מקפץ ותופים פשוטים. יואקם שר בקול גבוה, מתנגן ועצוב, עם מבטא כפרי עבה, כמו קאובוי עייף בסוף לילה ארוך. השירים עוסקים בלב שבור, בבדידות, בשתייה ובבית רחוק. Streets of Bakersfield הוא דואט עם באק אוונס בעצמו, שיצא במיוחד מפרישה, והגיע למקום הראשון במצעד הקאנטרי. I Sang Dixie הוא שיר נוגה על אדם מהדרום שמת לבד ברחובות לוס אנג׳לס. שיר הנושא, עם כותרת המשנה She Wore Red Dresses, הוא סיפור קודר של קנאה ונקמה, כמו בלדה מערבית ישנה. Home of the Blues הוא גרסה לשיר של ג׳וני קאש.''',
'''שני שירים מהאלבום הגיעו למקום הראשון במצעד הקאנטרי, והאלבום חיזק את מעמדו של יואקם כמי שמחזיר לקאנטרי את השורשים החשמליים שלו. הוא פתח את הדרך לזרם של קאנטרי חלופי, שהיה קרוב יותר לרוק ולבלוז מאשר לנאשוויל, והפך גם לשחקן קולנוע מוערך.''',
'''שמעו את Streets of Bakersfield, ואחריו את I've Got a Tiger by the Tail של באק אוונס (אלבום 47): תשמעו את המורה ואת התלמיד, בהפרש של עשרים שנה.''',
], [
('Streets of Bakersfield', 'דואט שמח עם באק אוונס, שיצא במיוחד מפרישה, והגיע למקום הראשון.'),
('I Sang Dixie', 'שיר נוגה על אדם מהדרום שמת לבד ברחובות לוס אנג׳לס, מרגש ויפה.'),
('Buenas Noches from a Lonely Room (She Wore Red Dresses)', 'סיפור קודר של קנאה ונקמה, כמו בלדה מערבית ישנה עם גיטרה מצלצלת.'),
])

add(633, [
'''ג׳יינס אדיקשן קמו בלוס אנג׳לס ב־1985, ובמרכזם הזמר פרי פארל, דמות תיאטרלית ופרועה, לצד הגיטריסט דייב נבארו, הבסיסט אריק אייברי והמתופף סטיבן פרקינס. הם חיברו בין רוק כבד בסגנון לד זפלין, פאנק, פסיכדליה ופאנק־רוק, והפכו לאחת הלהקות הבולטות של סצנת המועדונים של לוס אנג׳לס. Nothing's Shocking, אלבום האולפן הראשון שלהם, יצא ב־1988, עם עטיפה שפארל עיצב בעצמו, שעוררה מחלוקת וחלק מהחנויות סירבו למכור.''',
'''הצליל עשיר ומפתיע: הבס של אייברי מוביל עם קווים חוזרים ומהפנטים, הגיטרה של נבארו עוברת מריפים כבדים לצלילים חלומיים, ופארל שר בקול גבוה, חד ומהדהד, כמו כומר מוזר. Up the Beach פותח בקטע כלי שקט ויפה, כמו זריחה מעל הים. Ocean Size פורץ בעוצמה, ו־Mountain Song כבד ומאיים. Jane Says, השיר המוכר ביותר שלהם, מנוגן על גיטרות אקוסטיות ותופי פלדה קריביים, ומספר על חברה של הלהקה שחולמת לעזוב את הסמים ולנסוע לספרד, ולא מצליחה. Summertime Rolls איטי וחולמני, כמו ערב קיץ ארוך. Had a Dad ו־Pigs in Zen קצביים וסוערים, עם תופים של פרקינס שמזכירים מוזיקה שבטית.''',
'''האלבום השפיע על הרוק האלטרנטיבי של שנות התשעים, ופארל הפך לאחד היזמים החשובים שלו: ב־1991 הוא הקים את פסטיבל לולפלוזה, שהביא להקות אלטרנטיביות לקהל ענק ברחבי אמריקה, ונמשך עד היום.''',
'''שמעו את Up the Beach ואחריו את Jane Says: הפתיחה הכי שקטה והשיר הכי רך באלבום. רק אחר כך עברו ל־Ocean Size ו־Mountain Song, כדי לשמוע את הצד הסוער של הלהקה.''',
], [
('Jane Says', 'שיר אקוסטי עם תופי פלדה על חברה שחולמת לעזוב הכל ולנסוע לספרד.'),
('Up the Beach', 'הפותח, קטע כלי שקט ויפה עם בס מהפנט, כמו זריחה מעל הים.'),
('Mountain Song', 'שיר כבד ומאיים, עם ריף ענק וקול גבוה ומהדהד של פרי פארל.'),
])

add(634, [
'''פאבליק אנמי קמו בלונג איילנד שליד ניו יורק, ובראשם הראפר צ׳אק די, עם קול עמוק וכבד כמו של נואם, ולצדו פלייבור פלאב, הליצן של הקבוצה, עם שעון ענק תלוי על הצוואר. It Takes a Nation of Millions to Hold Us Back, שיצא ב־1988, הוא אלבומם השני, וההפקה שלו נעשתה על ידי צוות בשם "הבומב סקווד", בהובלת הנק שוקלי. הם בנו את השירים משכבות על גבי שכבות של דגימות: צפירות, נאומים, תופים, שריקות, קטעי סול ופאנק, רעשים ושברי צלילים.''',
'''התוצאה נשמעת כמו מהומה ברחוב או כמו שידור חדשות שהשתבש: צפוף, רועש, מהיר ומלא מתח. מעל הכל צ׳אק די מדבר על גזענות, על התקשורת, על הכלא, על סמים בשכונות השחורות ועל היסטוריה שחורה, ופלייבור פלאב קוטע אותו בצעקות ובצחוק. Bring the Noise פותח בצפירות ובכעס. Don't Believe the Hype תוקף את העיתונות. Black Steel in the Hour of Chaos הוא סיפור על בריחה מבית כלא, על לופ איטי ומאיים. Night of the Living Baseheads עוסק בהתמכרות לקראק, ו־Rebel Without a Pause בנוי על צליל של סקסופון שנשמע כמו צפירה שלא נגמרת.''',
'''האלבום נחשב לאחד מאלבומי ההיפ הופ החשובים ביותר, ונבחר לארכיון ההקלטות הלאומי של ספריית הקונגרס האמריקאית. הוא הוכיח שראפ יכול להיות פוליטי, מחאתי ומורכב כמו כל רוק. צל עליו הטילו התבטאויות אנטישמיות של אחד מחברי הקבוצה, פרופסור גריף, ב־1989, שבעקבותיהן הורחק לזמן מה.''',
'''זה אלבום שצריך לשמוע בקול רם, כמו בהופעה. התחילו ב־Rebel Without a Pause ו־Black Steel in the Hour of Chaos, ושימו לב לשכבות של הצלילים מאחורי הקול.''',
], [
('Bring the Noise', 'שיר פותח זועם עם צפירות ותופים, שמכריז על כל מה שעומד לבוא.'),
('Black Steel in the Hour of Chaos', 'סיפור על בריחה מבית כלא, על לופ איטי ומאיים של פסנתר.'),
('Rebel Without a Pause', 'שיר מהיר וזועם, עם צליל סקסופון שנשמע כמו צפירה שלא נגמרת.'),
])

add(635, [
'''פיית׳ נו מור קמו באזור סן פרנסיסקו בתחילת שנות השמונים, ועברו כמה זמרים עד שמצאו את מייק פאטון, צעיר בן 21 מלהקה ניסיונית בשם מיסטר באנגל. הוא הצטרף ללהקה כשרוב המוזיקה ל־The Real Thing כבר הייתה מוכנה, וכתב את כל המילים בשבועות ספורים. האלבום יצא ב־1989, ובהתחלה כמעט לא הצליח, עד שהקליפ של Epic הגיע ל־MTV, והפך את הלהקה לכוכבת.''',
'''המוזיקה מחברת מטאל כבד עם פאנק, ראפ, קלידים דרמטיים ומנגינות פופ. הבס של בילי גולד מוביל, הגיטרות של ג׳ים מרטין כבדות, והקלידים של רודי בוטום מוסיפים צליל כמעט תזמורתי. פאטון שר בעשרה קולות שונים: ראפ, שירה מלודית, צעקות ולחישות. Epic, הלהיט, עובר מראפ כועס לפזמון ענק, ומסתיים בקטע פסנתר שקט ויפה. From Out of Nowhere פותח בקלידים מהירים ובאנרגיה של פופ. Falling to Pieces קופצני ובנוי על בס מצוין. שיר הנושא ארוך ואפל, ו־Zombie Eaters מתחיל כמו שיר ערש ומתפוצץ. Underwater Love מהיר ומלא מתח, ו־Woodpecker from Mars הוא קטע כלי מוזר ומהיר, עם קלידים שנשמעים כמו כינור.''',
'''The Real Thing היה אחד האלבומים הראשונים שחיברו בהצלחה מטאל וראפ, והשפיע על כל זרם ה"ניו מטאל" של שנות התשעים, למרות שהלהקה עצמה לא אהבה את ההשוואה. פאטון הפך לאחד הזמרים המגוונים והניסיוניים של הרוק.''',
'''שמעו את Epic עד הסוף, וחכו לפסנתר בדקה האחרונה: שקט מפתיע אחרי הסערה. ואחר כך נסו את Paranoid של בלאק סבאת׳ (אלבום 184), שממנו לקחו את War Pigs, שהקליטו בגרסה משלהם.''',
], [
('Epic', 'הלהיט, ראפ כועס שהופך לפזמון ענק, ומסתיים בפסנתר שקט ויפה.'),
('From Out of Nowhere', 'הפותח, קלידים מהירים, בס חזק ואנרגיה של שיר פופ גדול.'),
('Falling to Pieces', 'שיר קופצני ובנוי על בס מצוין, עם פזמון שקל לשיר.'),
])

add(636, [
'''לני קרביץ גדל בניו יורק ובלוס אנג׳לס, בן לשחקנית רוקסי רוקר ולמפיק טלוויזיה, ובבית שלו ביקרו מוזיקאי ג׳אז ידועים. כבר כילד הוא ניגן בכמה כלים, ובצעירותו הקליט באולפן כמעט לבד. Let Love Rule, אלבום הבכורה, יצא ב־1989, בזמן שרוב המוזיקה נשמעה מלאכותית ואלקטרונית, וקרביץ הלך הפוך: הוא הקליט על ציוד ישן ואנלוגי, וניגן בעצמו גיטרות, בס, תופים וקלידים, כדי להישמע כמו התקליטים של סוף שנות השישים.''',
'''הצליל חם ורטרו: גיטרות מחוספסות, תופים יבשים, אורגן, כלי נשיפה וקולות רקע של סול. אפשר לשמוע בו את ג׳ון לנון, ג׳ימי הנדריקס, קרטיס מייפילד וסטיבי וונדר, ובכל זאת הוא נשמע אישי. Let Love Rule, שיר הנושא, הוא המנון אופטימי על אהבה, שמתחיל בשקט ובונה את עצמו לשיא של מקהלה. Mr. Cab Driver הוא שיר רוק כועס על נהגי מוניות שלא עוצרים לאדם שחור. I Build This Garden for Us הוא שיר אהבה פסיכדלי לאשתו דאז, השחקנית ליסה בונה, שהייתה שותפה לכתיבת חלק מהשירים. Be רך ושקט, ו־Fear הוא שיר סול איטי ומהורהר. Freedom Train קצבי ומלא שמחה, כמו שיר רוקנרול של סוף שנות השישים.''',
'''האלבום התקבל בהתחלה בספקנות, ומבקרים טענו שקרביץ רק מחקה את גיבוריו. אבל הוא בנה לעצמו קהל נאמן, ובשנות התשעים הפך לכוכב רוק עולמי, עם להיטים כמו Are You Gonna Go My Way ו־Fly Away.''',
'''שמעו את Let Love Rule עד הסוף, ותנו לו להיבנות. ואחר כך שמעו את Electric Ladyland של ג׳ימי הנדריקס (אלבום 113), אחד המקורות הברורים של קרביץ.''',
], [
('Let Love Rule', 'שיר הנושא, המנון אופטימי שמתחיל בשקט ונבנה לאט לשיא של מקהלה ושמחה.'),
('Mr. Cab Driver', 'שיר רוק כועס על נהגי מוניות שלא עוצרים לאדם שחור, עם גיטרה מחוספסת.'),
('I Build This Garden for Us', 'שיר אהבה פסיכדלי ורך, עם גיטרות חולמניות וקולות רקע של סול.'),
])

add(637, [
'''ג׳ון לי הוקר נולד במיסיסיפי, כנראה ב־1912, ועבר לדטרויט, שם הקליט ב־1948 את Boogie Chillen, אחד מאבני היסוד של הבלוז החשמלי. הסגנון שלו היה ייחודי: גיטרה אחת, רגל שמקישה על הרצפה, וקול עמוק שמדבר ושר כמעט בלי לשנות אקורדים, בקצב "בוגי" מהפנט. בשנות השמונים הוא היה כבר בן שבעים ויותר, וכמעט נשכח. The Healer, שיצא ב־1989, החזיר אותו לחיים: אלבום שבו הוא מנגן עם כוכבי רוק ובלוז צעירים יותר, שגדלו על המוזיקה שלו.''',
'''המפיק, גיטריסט הסלייד רוי רוג׳רס, הזמין לאלבום אורחים רבים, וכל אחד מהם מביא צבע משלו. בשיר הנושא, The Healer, מנגן קרלוס סנטנה עם להקתו, בקצב לטיני מהפנט, והגיטרה שלו מדברת עם הקול העמוק של הוקר. I'm in the Mood הוא דואט חושני ואיטי עם הזמרת והגיטריסטית בוני רייט, שזכה בפרס גראמי. Baby Lee מנוגן עם רוברט קריי. בכמה שירים מלווים אותו לוס לובוס וקאנד היט, ובאחרים הוקר יושב לבד עם הגיטרה, ומזכיר מאיפה הכל התחיל.''',
'''The Healer היה אחד מאלבומי הבלוז המצליחים ביותר אי פעם, והפך את הוקר, כשהוא כבר בשנות השבעים לחייו, לכוכב מחדש. בשנים שנשארו לו הוא הקליט עוד אלבומים, הופיע בפסטיבלים גדולים וזכה בפרסים, עד מותו ב־2001. האלבום עזר גם להחזיר את הבלוז הישן לקהל צעיר.''',
'''שמעו את I'm in the Mood בשקט, ותנו לשני הקולות להתלחשש. ואחר כך שמעו את Muddy Waters at Newport (אלבום 29), כדי לשמוע עוד ענק של הבלוז החשמלי, בשיאו.''',
], [
('The Healer', 'שיר הנושא, עם קרלוס סנטנה ולהקתו, בקצב לטיני מהפנט וגיטרה שמדברת.'),
("I'm in the Mood", 'דואט חושני ואיטי עם בוני רייט, שזכה בפרס גראמי לבלוז.'),
('Baby Lee', 'שיר בלוז שמח וקופצני עם רוברט קריי, שתי גיטרות מדברות זו עם זו.'),
])

add(638, [
'''ניו אורדר כבר הופיעו כאן עם Low-Life (אלבום 560). Technique, שיצא ב־1989, הוקלט ברובו באי איביזה שבספרד, בזמן שמוזיקת האסיד האוס ומסיבות הקיץ של האי שינו את מוזיקת הריקודים באירופה. הלהקה בילתה שם הרבה במסיבות, ולפי הסיפורים עבדה מעט מאוד, אבל האלבום שיצא מהקיץ הזה הוא אחד הטובים שלהם, והראשון שלהם שהגיע למקום הראשון במצעד הבריטי.''',
'''האלבום מחולק כמעט שווה בשווה בין שירי ריקוד אלקטרוניים, עם בס של מכונה ותופים של מועדון, לבין שירי גיטרה מלודיים ומלנכוליים, עם הבס הגבוה והמוכר של פיטר הוק. Fine Time פותח בצליל אסיד האוס מקפץ, עם קול עמוק ומעוות שצוחק על זמרי ההוסט של אותה תקופה. All the Way ו־Run הם שירי גיטרה יפים ושמשיים. Round & Round הוא שיר ריקוד מושלם, עם מנגינה עצובה. Vanishing Point קודר ומהיר, ו־Dream Attack, הסוגר, הוא אחד השירים היפים ביותר שכתבו, עם גיטרה מתנגנת וקצב שלא עוצר. Love Less ו־Guilty Partner רכים ושקטים יותר, עם גיטרות אקוסטיות וקול עייף.''',
'''Technique נחשב לאלבום שבו ניו אורדר הצליחו לחבר בצורה מושלמת את שני העולמות שלהם, הרוק העצוב של מנצ׳סטר ומוזיקת המועדונים, בדיוק ברגע שבו כל אנגליה רקדה. הוא השפיע על סצנת "מאדצ׳סטר" ועל מוזיקת האינדי־דאנס של שנות התשעים.''',
'''שמעו את Fine Time ואחר כך את Dream Attack: האלבום כולו נע בין שני הקטבים האלה. ואם אתם רוצים עוד מאותו קיץ, שמעו את Bummed של הפי מאנדיז (אלבום 618).''',
], [
('Fine Time', 'הפותח, אסיד האוס מקפץ עם קול עמוק ומעוות שצוחק על זמרי התקופה.'),
('Round & Round', 'שיר ריקוד מושלם עם מנגינה עצובה, כל הקסם של ניו אורדר בשיר אחד.'),
('Dream Attack', 'הסוגר, גיטרה מתנגנת וקצב שלא עוצר, אחד השירים היפים שכתבו.'),
])

add(639, [
'''בסוף שנות השמונים מדונה הייתה כבר הזמרת המפורסמת בעולם, עם להיטי ריקוד ותדמית פרובוקטיבית. Like a Prayer, שיצא ב־1989, הוא האלבום שבו היא רצתה להיות גם אמנית רצינית ואישית. היא כתבה והפיקה אותו יחד עם פטריק לאונרד וסטיבן בריי, ועסקה בו בדברים שנגעו בה מקרוב: הילדות בבית קתולי אדוק, מות אמה כשהייתה בת חמש, היחסים עם אביה, והגירושים שלה מהשחקן שון פן.''',
'''הצליל מגוון ועשיר: פופ, גוספל, פאנק, בלדות, קצת פסיכדליה של שנות השישים וכלי מיתר. Like a Prayer, שיר הנושא, מתחיל בגיטרה שקטה ומתפוצץ לגוספל ענק עם מקהלה של כנסייה. הקליפ שלו, עם צלבים בוערים וסיפור על צדק וגזענות, עורר סערה, ובעקבותיו חברת משקאות גדולה ביטלה פרסומת עם מדונה. Express Yourself הוא המנון פאנקי לנשים, שקורא להן לא להסתפק בפחות ממה שמגיע להן. Cherish קליל ושמח, Oh Father הוא בלדה כואבת לאביה, ו־Promise to Try הוא שיר פרידה עדין מאמה. Love Song הוא דואט מוזר ויפה עם פרינס.''',
'''Like a Prayer נחשב לאחד האלבומים הטובים של מדונה, והוכיח שהיא יותר מכוכבת פופ: אמנית שיודעת להשתמש במוזיקה, בתמונה ובשערורייה כדי לדבר על דברים חשובים. הקליפים של התקופה, ובמיוחד Express Yourself שביים דייוויד פינצ׳ר, הפכו לחלק מההיסטוריה של הקליפ. האלבום הגיע למקום הראשון ביותר מעשר מדינות, וכמעט כל הסינגלים שלו הפכו ללהיטים.''',
'''שמעו את Like a Prayer עד הסוף, ושימו לב לרגע שבו המקהלה נכנסת. ואחר כך שמעו את Promise to Try בשקט, הצד הכי עדין של מדונה.''',
], [
('Like a Prayer', 'מתחיל בגיטרה שקטה ומתפוצץ לגוספל ענק עם מקהלה, אחד השיאים של מדונה.'),
('Express Yourself', 'המנון פאנקי לנשים, שקורא להן לא להסתפק בפחות ממה שמגיע להן.'),
('Promise to Try', 'שיר פרידה עדין ומרגש מאמה, שמתה כשהייתה ילדה, בליווי פסנתר.'),
])

add(640, [
'''קווין לטיפה, שנולדה בשם דנה אוונס, גדלה בניוארק שבניו ג׳רזי, והייתה רק בת 19 כשהוציאה את All Hail the Queen ב־1989. היא הייתה חלק מקבוצה של אמני היפ הופ בשם "נייטיב טאנגס", יחד עם דה לה סול והג׳אנגל ברדרס, שהביאו להיפ הופ צבעים חדשים: ג׳אז, הומור, אפריקה ומסרים חיוביים. בזמן שרוב הראפרים היו גברים, לטיפה עמדה במרכז הבמה בבגדים אפריקאיים, עם ביטחון של מלכה.''',
'''הצליל מגוון: היפ הופ קשה, רגאיי, ג׳אז, ואפילו מוזיקת האוס של מועדונים. לטיפה חורזת בקול עמוק ובטוח, ולפעמים עוברת לשירה או לטוסטינג בסגנון ג׳מייקני. Ladies First, דואט עם הראפרית הבריטית מוני לאב, הוא המנון פמיניסטי שמזכיר לכולם שנשים היו שם מההתחלה, והקליפ שלו הציג דמויות של נשים שחורות חשובות בהיסטוריה ותמונות מהמאבק באפרטהייד. Come into My House הוא שיר האוס קופצני לרחבת הריקודים. Mama Gave Birth to the Soul Children הוא שיר עליז עם דה לה סול, ו־Wrath of My Madness מציג אותה כראפרית קשוחה.''',
'''All Hail the Queen פתח דלת לנשים רבות בהיפ הופ, ו־Ladies First נחשב לאחד השירים החשובים של הראפ הפמיניסטי. לטיפה הפכה בהמשך גם לשחקנית מצליחה, הייתה מועמדת לאוסקר, והייתה אמנית ההיפ הופ הראשונה שזכתה בכוכב בשדרת התהילה בהוליווד.''',
'''שמעו את Ladies First, ושימו לב איך שתי הראפריות, האמריקאית והבריטית, עונות זו לזו. ואחר כך נסו את It Takes a Nation of Millions של פאבליק אנמי (אלבום 634), עוד צד של ההיפ הופ באותן שנים.''',
], [
('Ladies First', 'המנון פמיניסטי עם מוני לאב, שמזכיר שנשים היו בהיפ הופ מההתחלה.'),
('Come into My House', 'שיר האוס קופצני לרחבת הריקודים, שמראה צד אחר ומפתיע של לטיפה.'),
('Mama Gave Birth to the Soul Children', 'שיר עליז ומשחקי עם דה לה סול, כמו מסיבה בין חברים.'),
])

add(641, [
'''ספייסמן 3 באו מראגבי, עיירה במרכז אנגליה, ובמרכזם שני חברים, פיטר קמבר וג׳ייסון פירס, שהיו ידועים בכינויים סוניק בום וג׳ייסון. הם אהבו את הוולווט אנדרגראונד (אלבום 91), את הסטוג׳ס ואת הגוספל, ושאפו ליצור מוזיקה שתגרום למאזין לשכוח את הזמן. הם הקפידו על מעט אקורדים, הרבה חזרות, וצליל שמתפשט לאט. Playing with Fire, שיצא ב־1989, הוא אלבומם השלישי, והוא שקט, יפה ומהפנט יותר מקודמיו.''',
'''יש כאן שני סוגים של שירים. חלקם שקטים וחלומיים, עם אורגן, גיטרה רכה ושירה לוחשת, כמו מזמורי כנסייה איטיים, ואחרים רועשים ומזמזמים, עם גיטרות מעוותות שחוזרות על אותו אקורד שוב ושוב עד שהשיר נשמע כמו מנוע. Honey הוא שיר אהבה שקט ומתוק. Come Down Softly to My Soul נשמע כמו מזמור. Revolution הוא שיר רועש וכועס, עם גיטרה אחת מזמזמת וקריאה למהפכה. Suicide הוא קטע רועש ארוך, שנקרא כמחווה ללהקה האמריקאית סואיסייד. החזרות הארוכות יוצרות תחושה של טקס, כמו מנטרה שחוזרת שוב ושוב עד שהיא נבלעת בגוף.''',
'''המוזיקה של ספייסמן 3 השפיעה על להקות רבות של שנות התשעים, שחיברו רוק שקט, חזרתי וחלומי. ג׳ייסון פירס הקים אחר כך את ספיריצ׳ואלייזד, וסוניק בום המשיך בפרויקטים ניסיוניים. לצד הצליל, הלהקה התפרסמה גם בגלל שדיברה בגלוי על השימוש שלה בסמים, וזה חלק מהסיפור שלה. השם שלהם עצמו, "אנשי החלל 3", מרמז על המסע הפנימי שהמוזיקה שלהם ניסתה ליצור.''',
'''זה אלבום לשעות הלילה המאוחרות. שמעו את Honey ו־Come Down Softly to My Soul בשקט, ואחר כך את Revolution בקול רם.''',
], [
('Honey', 'שיר אהבה שקט ומתוק, עם אורגן רך ושירה לוחשת, כמו חלום.'),
('Come Down Softly to My Soul', 'שיר איטי ויפה כמו מזמור, עם גיטרה רכה ותחושת שלווה.'),
('Revolution', 'שיר רועש וכועס, עם גיטרה מזמזמת אחת וקריאה פשוטה למהפכה.'),
])

add(642, [
'''פיירהוז נולדה מתוך טרגדיה: ב־1985 נהרג ד. בון, הזמר והגיטריסט של המינוטמן (אלבום 542), בתאונת דרכים, ושני חבריו, הבסיסט מייק וואט והמתופף ג׳ורג׳ הרלי, חשבו להפסיק לנגן. אז הגיע מעריץ צעיר מאוהיו, אד קרופורד, שנסע עד קליפורניה ושכנע אותם להקים איתו להקה חדשה. השם fROMOHIO, "מאוהיו", שיצא ב־1989, הוא מחווה צוחקת אליו. זה האלבום השלישי שלהם, והאחרון בחברת SST העצמאית.''',
'''הסגנון ממשיך את המינוטמן: שירים קצרים, פאנק שמשתלב בג׳אז ובפאנק, בס שמוביל ומנגן מנגינות שלמות, ותופים גמישים וחכמים. קרופורד מוסיף גיטרה אקוסטית ולמחצה חשמלית, קול רך ושירים כמעט פולקיים. וואט שר כמה שירים בקול עמוק ומדבר, עם הומור ופוליטיקה. Time with You הוא שיר אהבה פשוט ויפה. Some Things הוא פאנק קצבי ומקפץ. In My Mind מתחיל שקט ומתפתח לאט, ויש באלבום גם קטעים קצרים ומוזרים, כמו סקיצות. השירים נשמעים כמו שיחה בין שלושה חברים שמנגנים יחד באולפן קטן.''',
'''פיירהוז לא הפכו לכוכבים, אבל הוכיחו שאפשר להמשיך אחרי אובדן, ושהרוח של המינוטמן לא מתה. וואט המשיך לנגן עם הסטוג׳ס ועם מוזיקאים רבים, והפך לאחת הדמויות האהובות של הרוק העצמאי האמריקאי, בזכות האמונה שלו בעשייה עצמאית ובלי פשרות. השם הצוחק של הלהקה, "צינור כיבוי אש", נבחר כמחווה לשיר של בוב דילן.''',
'''שמעו את Time with You, ואחריו את Double Nickels on the Dime של המינוטמן (אלבום 542). תשמעו את אותו בס ואת אותה רוח, בלב שבור ושלם מחדש.''',
], [
('Time with You', 'שיר אהבה פשוט ויפה, עם גיטרה רכה ובס שמנגן מנגינה שלמה.'),
('Some Things', 'פאנק קצבי ומקפץ, עם תופים גמישים ובס מוביל של מייק וואט.'),
('In My Mind', 'שיר שמתחיל שקט ומתפתח לאט, כמו מחשבה שגדלה בראש.'),
])

add(643, [
'''אחרי ההצלחה הענקית של Licensed to Ill (אלבום 566), הביסטי בויז עזבו את דף ג׳אם, עברו ללוס אנג׳לס, והתחילו לעבוד עם צמד מפיקים צעיר בשם הדאסט ברדרס. התוצאה, Paul's Boutique, שיצא ב־1989, הייתה שונה לגמרי: במקום גיטרות רוק ובדיחות של נערים, היה כאן קולאז׳ ענק של מאות דגימות מכל תולדות המוזיקה, מהביטלס ועד פאנק של שנות השבעים, ומילים חכמות ומצחיקות על החיים בניו יורק.''',
'''כל שיר נשמע כמו מסיבה שבה מתנגנים עשרה תקליטים בבת אחת, אבל הכל מתחבר לגרוב אחד, חם ורגוע. שלושת החברים חורזים מהר, משלימים זה את המשפטים של זה, ומפזרים שמות של סרטים, ספורטאים ודמויות מהתרבות האמריקאית. Shake Your Rump בנוי על גרוב פאנקי מקפץ. Hey Ladies, הסינגל, הוא שיר מסיבה עם פעמון פרה ובס דיסקו. Shadrach מבוסס על סיפור התנ״ך על שדרך, מישך ועבד־נגו, בתוך שכבות של פאנק ורוק. B-Boy Bouillabaisse, הסוגר, הוא יצירה של שתים־עשרה דקות שבנויה מתשעה קטעים קצרים, כמו סיור בניו יורק.''',
'''בזמנו האלבום מכר הרבה פחות מהצפוי, וחברת התקליטים איבדה בו עניין. אבל עם השנים הוא נחשב ליצירת מופת של אמנות הדגימה, ולאחד מאלבומי ההיפ הופ החשובים בכל הזמנים. היום כבר כמעט אי אפשר לעשות אלבום כזה, כי השימוש בדגימות הפך להיות יקר מאוד.''',
'''שמעו את Shadrach עם אוזניות, ונסו לזהות כמה צלילים שונים מסתתרים בו. ואחר כך חזרו ל־Licensed to Ill (אלבום 566), כדי לשמוע כמה הלהקה התבגרה בשלוש שנים.''',
], [
('Shadrach', 'שיר על סיפור התנ״ך של שדרך, מישך ועבד־נגו, בתוך שכבות של פאנק ורוק.'),
('Hey Ladies', 'הסינגל, שיר מסיבה עם פעמון פרה, בס דיסקו וחרוזים מצחיקים.'),
('Shake Your Rump', 'גרוב פאנקי ומקפץ, עם שלושה ראפרים שמשלימים זה את זה.'),
])

add(644, [
'''היאנג גודס באו מז׳נבה שבשווייץ, ובמרכזם הזמר פרנץ טרייכלר, שרצה ליצור רוק בלי גיטרות. במקום גיטריסט, היה להם נגן דוגם, שהשתמש בקטעים מוקלטים של גיטרות, תזמורות קלאסיות, ומוזיקה מכל מקום, וניגן אותם על קלידים בזמן אמת. L'eau rouge, "המים האדומים", שיצא ב־1989, הוא אלבומם השלישי, והוא חיבור מוזר ועוצמתי בין מוזיקה תעשייתית, רוק, קברט וקלאסיקה.''',
'''הצליל כבד ודרמטי: דגימות של גיטרות שנשמעות כמו קיר, תופים חזקים, תזמורת מתנפצת, וטרייכלר שר ונוהם בצרפתית ובאנגלית, כמו שחקן בתיאטרון אפל. La fille de la mort, הפותח, נמשך שמונה דקות ונשמע כמו שיר עם צרפתי שהפך לסיוט. שיר הנושא, L'eau rouge, הוא גל של צליל כבד ומאיים. Longue route שקט ומהורהר יותר, כמו נסיעה בלילה. Charlotte קצר, מוזר ויפה, בצליל של קברט ישן, ו־Ville nôtre מהיר ומלא אנרגיה. השירים משלבים גם צלילים של כלי נשיפה, פסנתר ושירת מקהלה, כך שלפעמים קשה לדעת מה אמיתי ומה דגום.''',
'''היאנג גודס השפיעו מאוד על המוזיקה התעשייתית ועל להקות כמו ניין אינץ׳ ניילז, שחבריהן הזכירו אותם כהשראה. הם הוכיחו שאפשר לעשות רוק כבד ועוצמתי בעזרת מחשבים ודגימות, הרבה לפני שזה הפך לנפוץ, ונשארו פעילים עד היום. באותה תקופה הם הקליטו גם אלבום שלם של שירי קורט וייל, המלחין של "אופרה בגרוש".''',
'''שמעו את שיר הנושא בקול רם, ושימו לב שאין בו גיטרה אמיתית אחת. ואחר כך נסו את Opus Dei של לייבאך (אלבום 602), עוד להקה אירופית שחיברה רוק, מקהלות ומוזיקה תעשייתית.''',
], [
("L'eau rouge", 'שיר הנושא, גל של צליל כבד ומאיים, בלי גיטרה אמיתית אחת.'),
('La fille de la mort', 'הפותח, שמונה דקות של שיר עם צרפתי שהפך לסיוט כבד ומהפנט.'),
('Longue route', 'שיר שקט ומהורהר יותר מהשאר, כמו נסיעה בלילה בכביש ריק.'),
])

add(645, [
'''ג׳ון זורן הוא סקסופוניסט ומלחין ניו יורקי, מהדמויות המרכזיות של הסצנה הניסיונית של מנהטן, שאוהב לחבר בין ג׳אז, פאנק, מוזיקת סרטים, מוזיקה יהודית ורעש. אורנט קולמן היה אחד מגדולי הג׳אז החופשי, שבסוף שנות החמישים שחרר את הג׳אז מהכללים של האקורדים, וכתב מנגינות פשוטות ומפתיעות. ב־Spy vs. Spy, שיצא ב־1989, זורן לקח שבעה־עשר מהשירים של קולמן, וניגן אותם במהירות ובעוצמה של להקת הארדקור פאנק.''',
'''ההרכב מיוחד: שני סקסופונים אלט, של זורן ושל טים ברן, שני מתופפים, ג׳ואי ברון ומייקל וואצ׳ר, ובסיסט אחד, מארק דרסר. רוב הקטעים קצרים מאוד, דקה או שתיים: הנגנים מנגנים את המנגינה של קולמן פעם אחת, במהירות, ואז מתפוצצים לאלתור של צרחות סקסופון ומכות תופים, וחוזרים למנגינה כאילו לא קרה כלום. זה נשמע כמו ויכוח סוער בין שני אנשים, ולכן גם השם, על שם הקומיקס הישן של המגזין "מד", שבו שני מרגלים נלחמים זה בזה בלי סוף. Chronology, Good Old Days ו־Blues Connotation הם מהקטעים המוכרים של קולמן, שנשמעים כאן מטורפים, מצחיקים ומלאי חיים.''',
'''האלבום הראה שהג׳אז החופשי של שנות החמישים והפאנק של שנות השמונים הם בעצם קרובי משפחה. זורן המשיך לעשות מאות אלבומים, הקים את חברת התקליטים צדיק, ויצר את "מסדה", פרויקט ענק של מוזיקה יהודית חדשה, שבו ג׳אז נפגש עם מנגינות יהודיות עתיקות.''',
'''זה אלבום סוער מאוד. נסו לשמוע קטע אחד או שניים בכל פעם, ושימו לב לרגע שבו המנגינה חוזרת אחרי הסערה, כמו שמש אחרי סופה.''',
], [
('Chronology', 'מנגינה מוכרת של אורנט קולמן, שמנוגנת כאן במהירות מטורפת ובשמחה פרועה.'),
('Good Old Days', 'קטע קצר וסוער, עם שני סקסופונים שצורחים זה על זה ותופים כפולים.'),
('Blues Connotation', 'בלוז של קולמן שהפך לסערת פאנק, ואז חוזר בשלום למנגינה.'),
])

add(646, [
'''הסטון רוזס באו ממנצ׳סטר, ארבעה חברים שאהבו את הרוק של שנות השישים, את הביטלס ואת הבירדס, אבל גם את מוזיקת הריקודים החדשה של המועדונים. הזמר איאן בראון, עם קול רך וגישה יהירה, הגיטריסט ג׳ון סקוויר, שהיה גם צייר, הבסיסט מאני והמתופף רני, יצרו יחד צליל קליל, מתנגן ורוקד. אלבום הבכורה שלהם יצא ב־1989, בהפקת ג׳ון לקי, ועל העטיפה ציור של סקוויר בהשראת ג׳קסון פולוק, עם לימונים, מחווה למהפכת הסטודנטים של פריז ב־1968.''',
'''הצליל בהיר ושמשי: גיטרות מצלצלות ומבהיקות, בס מקפץ ומלודי, תופים גמישים עם קצב כמעט של פאנק, ושירה רכה וחולמנית. I Wanna Be Adored פותח בבס שמתגנב מתוך השקט, וגדל לאט לשיר על רצון להיות נערץ. She Bangs the Drums הוא שיר שמח על אהבה ראשונה. Waterfall הוא שיר יפה עם גיטרה מתגלגלת, ו־Don't Stop הוא אותו שיר, מנוגן הפוך. Made of Stone קודר ויפה, ו־I Am the Resurrection, הסוגר, נמשך שמונה דקות, ומסתיים בקטע כלי ארוך ומרקד.''',
'''האלבום הפך את הסטון רוזס לגיבורים של דור שלם בבריטניה, ויחד עם הפי מאנדיז (אלבום 618) הוביל את סצנת "מאדצ׳סטר". הוא השפיע ישירות על להקות הבריטפופ של שנות התשעים, כמו אואזיס, והופעה ענקית שלהם באי ספייק ב־1990 נחשבת לאגדה. האלבום השני שלהם, שיצא רק חמש שנים אחר כך, לא עמד בציפיות.''',
'''שמעו את I Wanna Be Adored מההתחלה, וחכו לבס שמתגנב מתוך השקט. ואחר כך שמעו את Waterfall ומיד אחריו את Don't Stop, כדי לשמוע את אותו שיר פעמיים.''',
], [
('I Wanna Be Adored', 'הפותח, בס שמתגנב מתוך השקט וגדל לאט לשיר על רצון להיות נערץ.'),
('Waterfall', 'שיר יפה ושמשי, עם גיטרה מתגלגלת כמו מים ושירה רכה וחולמנית.'),
('I Am the Resurrection', 'הסוגר, שמונה דקות שמסתיימות בקטע כלי ארוך, מרקד ומשמח.'),
])

add(647, [
'''ננה צ׳רי נולדה בשטוקהולם שבשוודיה, לאם ציירת שוודית ולאב מסיירה לאון, וגדלה עם אביה החורג, חצוצרן הג׳אז האמריקאי דון צ׳רי, בבית מלא מוזיקה, נסיעות ואמנים. בגיל צעיר עברה ללונדון, שרה בלהקות פוסט־פאנק כמו ריפ ריג אנד פאניק, וכבר שמענו אותה כאן בדואט עם דה דה, ב־Infected (אלבום 568). Raw Like Sushi, אלבום הבכורה שלה, יצא ב־1989.''',
'''המוזיקה מחברת היפ הופ, פופ, פאנק וסול, עם ביטים של מכונות תופים, דגימות, בס עבה וכלי נשיפה. צ׳רי עוברת בקלות בין ראפ לשירה, בקול חם, בטוח ושובב, עם הרבה הומור וגישה של אישה שלא צריכה אישור מאף אחד. Buffalo Stance, הלהיט, הוא שיר ראפ־פופ חצוף וקופצני על בחורים שמנסים להרשים, והיא הופיעה איתו בטלוויזיה הבריטית כשהייתה בהיריון מתקדם, דבר שהיה אז מפתיע ושובר מוסכמות. Manchild הוא שיר רך ונוגה על גבר שמתנהג כמו ילד. Kisses on the Wind מספר על נערה שמתבגרת מהר מדי, ו־Inna City Mamma הוא שיר אמהות שקט על חיים בעיר הגדולה.''',
'''האלבום הצליח מאוד בבריטניה ובאמריקה, והשפיע על הסצנה של בריסטול, ועל להקות כמו מאסיב אטאק, שחבריה עבדו איתה. צ׳רי הראתה שאישה יכולה לעשות היפ הופ ופופ בדרך שלה, בלי לוותר על הקול שלה, וממשיכה ליצור עד היום, לבד ועם מוזיקאים אחרים.''',
'''שמעו את Buffalo Stance בקול רם, ואחר כך את Manchild בשקט. ואם אתם רוצים להכיר את הבית שממנו באה, נסו את Ladies First של קווין לטיפה (אלבום 640), שיצא באותה שנה.''',
], [
('Buffalo Stance', 'הלהיט, ראפ־פופ חצוף וקופצני על בחורים שמנסים להרשים ונכשלים.'),
('Manchild', 'שיר רך ונוגה על גבר שמתנהג כמו ילד, עם כלי מיתר וקצב איטי.'),
('Kisses on the Wind', 'שיר על נערה שמתבגרת מהר מדי, עם קצב רך וקול חם ושובב.'),
])

add(648, [
'''באבא מאל הוא זמר מסנגל, בן לעם הפולאני, שגדל בעיירה פודור, על גדות נהר סנגל בצפון המדינה. מנסור סק, חברו מילדות, הוא גיטריסט עיוור ממשפחה של גריוטים, מספרי סיפורים ומשמרי מסורת מוזיקלית. השניים נסעו יחד ללמוד מוזיקה, טיילו בכפרים של מערב אפריקה, ואספו שירים ומסורות. Djam Leelii הוקלט בתחילת שנות השמונים, ויצא באנגליה ב־1989, ואז הפך לאחד האלבומים האפריקאיים האהובים באירופה.''',
'''זה אלבום אקוסטי ושקט לגמרי: שתי גיטרות, כלי מיתר אפריקאיים מסורתיים, מעט כלי הקשה, ושני קולות. הקול של באבא מאל גבוה, חזק וצלול, ועולה מעל הגיטרות כמו קריאה מעל מים, ומנסור סק עונה לו בקול נמוך ורך. השירים בשפת הפולאר מספרים על היסטוריה, על אהבה, על מסורת ועל החיים לאורך הנהר. רבים השוו את הצליל לבלוז של דלתת המיסיסיפי, ובצדק: אפשר לשמוע כאן את השורשים האפריקאיים של הבלוז האמריקאי, שהגיעו לשם עם העבדים. הקצב איטי ומתמשך, כמו זרימה של נהר רחב בשעת אחר הצהריים.''',
'''Djam Leelii הפך את באבא מאל לכוכב בינלאומי, והוא המשיך להקליט אלבומים מגוונים, חלקם עם להקות חשמליות גדולות. האלבום נחשב לאחת היצירות היפות של המוזיקה המערב־אפריקאית, ואחד הטובים ביותר להתחיל ממנו את ההיכרות איתה. באבא מאל הופיע מאז בפסטיבלים גדולים בכל העולם, וגם שר בפסקול של סרט הוליוודי מצליח.''',
'''שמעו את האלבום ברצף, בשקט, אחר הצהריים. ואם אתם רוצים להשוות לסנגלי אחר, נסו את Immigrés של יוסו נדור (אלבום 544), שמשתמש בכלים חשמליים וקצבים מהירים.''',
], [
('Loodo', 'שיר שקט ויפה, עם שתי גיטרות שמשוחחות וקול צלול שעולה מעליהן.'),
('Salminanam', 'שיר אהבה רך ומתמשך, כמו זרימה של נהר רחב בשעת אחר הצהריים.'),
('Lam Tooro', 'שיר מסורת על ההיסטוריה של אזור הנהר, עם קריאות קול חזקות ומרגשות.'),
])

add(649, [
'''קייט בוש כבר הופיעה כאן עם The Dreaming (אלבום 505) ועם Hounds of Love (אלבום 556). The Sensual World, שיצא ב־1989, הוא אלבום רך, בוגר ואישי יותר, שבו היא כותבת על גוף, על אהבה, על משפחה ועל אובדן. שיר הנושא נכתב בהשראת המונולוג המפורסם של מולי בלום בסוף "יוליסס" של ג׳יימס ג׳ויס. בוש רצתה להשתמש במילים של ג׳ויס עצמן, אבל העיזבון שלו סירב, אז היא כתבה מילים משלה. רק כעשרים שנה אחר כך קיבלה רשות, והקליטה גרסה חדשה עם המילים המקוריות.''',
'''הצליל עשיר ושונה: יש כאן כלים איריים כמו פייפים וכינור, גיטרות של דייוויד גילמור מפינק פלויד, ושלוש זמרות מבולגריה, טריו בולגרקה, שהקולות המיוחדים שלהן מופיעים בשלושה שירים. Deeper Understanding מספר על אדם בודד שמוצא נחמה במחשב, שמדבר אליו ואוהב אותו, רעיון שנשמע היום כמעט כמו נבואה. This Woman's Work, שנכתב לסרט, הוא בלדת פסנתר כואבת על גבר שמחכה בבית חולים בזמן שאשתו בסכנה בלידה, ומבין כמה לא אמר לה. Love and Anger קצבי ומלא אנרגיה, ו־The Fog מתאר זיכרון ילדות של אב שמלמד את בתו לשחות.''',
'''The Sensual World הגיע למקום השני במצעד הבריטי, ו־This Woman's Work הפך לאחד השירים האהובים והמרגשים שלה, ששרים אותו זמרים רבים עד היום. האלבום מראה אמנית שמתבגרת בלי לאבד את הדמיון ואת האומץ.''',
'''שמעו את This Woman's Work לבד, בשקט, עם כוס תה. ואחר כך שמעו את Deeper Understanding, וחשבו כמה הוא נשמע עכשווי.''',
], [
("This Woman's Work", 'בלדת פסנתר כואבת על גבר שמחכה בבית חולים, ומבין כמה לא אמר.'),
('Deeper Understanding', 'אדם בודד שמוצא אהבה במחשב, עם קולות הזמרות הבולגריות, כמעט נבואה.'),
('The Sensual World', 'שיר הנושא, בהשראת יוליסס של ג׳ויס, עם פייפים איריים וקצב חושני.'),
])

add(650, [
'''הקיור כבר הופיעו כאן עם Seventeen Seconds (אלבום 460) ו־Pornography (אלבום 499), האפלים והקודרים. באמצע שנות השמונים הם הצליחו עם שירי פופ צבעוניים ושמחים יותר, כמו Just Like Heaven. אבל רוברט סמית׳, הזמר והכותב, התקרב לגיל שלושים, הרגיש מדוכא, ופחד שהלהקה הפכה לשמחה ומסחרית מדי. Disintegration, שיצא ב־1989, הוא החזרה לחושך, אבל הפעם עם יופי גדול, שלם ובוגר.''',
'''השירים ארוכים, איטיים ועשירים: קלידים כמו גשם, גיטרות מהדהדות, בס עמוק שמוביל ותופים איטיים, והקול של סמית׳ עצוב, רך ולפעמים בוכה. Plainsong, הפותח, מתחיל בצלילי פעמונים, ואז נפתח לגל ענק של קלידים, כמו שמיים אפורים. Pictures of You הוא שיר געגועים יפה ועצוב על תמונות של אהובה. Lovesong, שסמית׳ כתב כמתנת חתונה לאשתו מרי, הוא שיר אהבה פשוט, והגיע למקום השני במצעד האמריקאי. Lullaby הוא שיר ערש מפחיד על עכביש שבא לאכול את המספר בלילה. Fascination Street קצבי ואפל, ושיר הנושא הוא סערה של התפרקות. Prayers for Rain איטי ומעיק, ו־The Same Deep Water as You נמשך כמעט עשר דקות, כמו טביעה איטית ושקטה.''',
'''Disintegration הפך לאלבום המצליח ביותר של הקיור באותה תקופה, ונחשב היום ליצירת המופת שלהם, ולאחד האלבומים החשובים של הרוק הבריטי. הוא הוכיח שאפשר לעשות אלבום עצוב מאוד שגם נוגע ללב של מיליונים. בזמן ההקלטות עזב את הלהקה לול טולהרסט, חבר ילדות של סמית׳ ומהמייסדים שלה.''',
'''שמעו את Plainsong בחושך, ותנו לו לפתוח את האלבום כמו שצריך. ואחר כך עברו ל־Lovesong, שהוא הרגע האופטימי ביותר בכל האלבום.''',
], [
('Pictures of You', 'שיר געגועים יפה ועצוב על תמונות של אהובה, עם בס מוביל וקלידים רכים.'),
('Lovesong', 'מתנת חתונה של סמית׳ לאשתו, שיר אהבה פשוט שהפך ללהיט באמריקה.'),
('Plainsong', 'הפותח, פעמונים שקטים שנפתחים לגל ענק של קלידים, כמו שמיים אפורים.'),
])
